window.POEM_DB=window.POEM_DB||{};POEM_DB["song_051"]={"n":"邹浩","dyn":"宋","poems":[{"t":"湖上杂咏 其一","f":"七言绝句","c":["荷叶如钱三月时，幅巾藜杖一追随。","尔来胜事知多少，惟有风标公子知。"]},{"t":"陈满堂","f":"七言绝句","c":["满堂当日亦飞升，金笋无根不复生。","惟有明皇留辇处，至今云雾半山横。"]},{"t":"参寥示简元规诗用其韵寄之 其一","f":"七言绝句","c":["千岩万壑久青天，一钵新从淮上旋。","昨日浮云今止水，谁知庵内更无边。"]},{"t":"参寥示简元规诗用其韵寄之 其二","f":"七言绝句","c":["人间何向不盐梅，江海元从蚁穴开。","列戟门庭扫踪迹，只应飞矢亦潜来。"]},{"t":"柄生日","f":"七言绝句","c":["南极星中见老人，祥光垂照喜生春。","身如龟鹤心如石，进德功夫常日新。"]},{"t":"病卧读书","f":"七言绝句","c":["山为屏障草为裀，黄犊群中早奋身。","骨立诗书亦何有，不如参取坐忘人。"]},{"t":"跋漳浦李大忠微叔所藏书画尾","f":"七言绝句","c":["岭表归来饭不足，负郭有田多未赎。","何当卖剑成此谋，耕遍雨馀春雨绿。"]},{"t":"嘲龚彦和","f":"七言绝句","c":["衣领从教虱子缘，夜深拜得席儿穿。","道乡活计君知否，饥即须餐困即眠。"]},{"t":"白龙洞","f":"七言律诗","c":["洞门寂寂昼常阴，谁识行天济物心。","金翅影沉超永劫，玉毫光现契圆音。","滂沱普润三千界，叆叇浓兴一万寻。","天子六龙方在御，不应头角閟幽深。"]},{"t":"伯和见过","f":"七言律诗","c":["参军跋马瘴江滨，一笑相逢意转亲。","偶复面论前日事，恍疑身是隔生人。","风随玉麈倾新盖，暑避冰姿返旧轮。","八桂森森照归路，为君留饮判经旬。"]},{"t":"别由正","f":"七言律诗","c":["许汝相望无百里，政声文誉益惊人。","岂知今日俱长路，重慰平生仰后尘。","云澹京山黄鹄举，风回汉水白鸥驯。","归来有约天从否，准拟冥行细问津。"]},{"t":"次韵端夫闻江北水磨","f":"七言古诗","c":["万事根本初难明，声之所发由声声。","不有智者抉其□，直如宝剑埋丰城。","风生风济孰嘘吸，制作解成琴与筝。","矧兹江汉泻荆楚，含桃初熟飞流莺。","波涛暗逐岁月长，激激滩际春雷谹。","白沙湖边更湍急，五磨因缘资养生。","城中鞭驴喘欲死，亦或人劳僵自横。","借令麦破面浮玉，青蝇遽集争营营。","乃知此策最长利，朱墨岂复嗤南荣。","天轮地轴骇昼夜，彷佛飓扇吹苍瀛。","游江夫人俨然坐，蛟龙不动如石鲸。","只应神物亦持护，我辈何妨双耳清。"]},{"t":"别昭平","f":"五言律诗","c":["江山本无情，别去亦何语。","向来爽气中，食息三月许。","来非吾所求，去非吾所禦。","回首谢江山，吾今若轻举。"]},{"t":"别零陵","f":"五言古诗","c":["零陵讵中邦，道阻五千里。","我以放逐来，本非心乐只。","身止高山巅，忽忽弥半祀。","人情久自亲，况复多可喜。","坐使故乡念，如火沃之水。","罪大不得留，今兹动行李。","昭州虽岭南，流寓盖均耳。","倘未还庭闱，在彼犹在此。","胡然当作离，耿耿殊不已。","物我要兼忘，咄哉从此始。"]},{"t":"岑老书云远老法堂上草深一丈矣","f":"七言律诗","c":["建隆无复旧行踪，石塔开堂得远公。","衣挂六铢收法界，草深一丈见家风。","也知是汝远狮子，不分饶他岑大虫。","何日扬州船子去，木兰花里问真空。"]},{"t":"咏路","f":"五言古诗","c":["赤路如龙蛇，不知几千丈。","出没山水间，一下复一上。","伊予独何为，与之同俯仰。"]},{"t":"班超","f":"七言律诗","c":["功名从古病难成，况作天西绝域行。","纵有平陵同落落，其如卫候尚营营。","杀妻吴起终遭逐，上疏鸿卿不免刑。","定远独能逢圣主，千年万岁蔼嘉声。"]},{"t":"嘲仲益","f":"五言古诗","c":["低檐荫茅竹，陋如野人居。","夫子莞尔笑，曰此真吾庐。","庭前郁乔木，庭后犹榛芜。","芟削随手净，春兰植扶疏。","光影动窗几，馨香袭文书。","皎然纫佩心，邂逅同三闾。","尔来基构新，百事凌往初。","突兀焕华屋，茅竹扫莫馀。","双楠庭之珍，斩代殊荣枯。","要知碧油幢，特立当阶除。","念念入勋业，不与蓬荜俱。","兰虽不生门，安能逭诛锄。","剖琴如剖薪，烹鹤如烹鱼。","珠玉抵飞鸟，镈钟委洪炉。","逝矣覆辙存，来车犹此涂。","尚欲取脩竹，永以娱朝晡。","问竹竹无言，冷风一虚徐。"]},{"t":"送大受赴天官","f":"七言古诗","c":["元祐真人初御天，四门穆穆来忠言。","阆风学士望朝野，即日赐环司谏垣。","当时同列继登用，独先朝露归九原。","位不酬身在孙子，嶷嶷诸子声名喧。","叔也纵横五经内，娱目未始窥家园。","苟闻某所有贤者，弊车趼仆从之奔。","甘陵南北正分党，攘臂其间无怨恩。","未见其止见其进，会须一指收乾坤。","素冠俛首琴复御，鹏飞九万方化鲲。","于今怙恃只明主，肯与世俗均寒暄。","早年妙笔三千牍，矧已恸哭论元元。","韩城父老傥改作，为报及此高闾门。"]},{"t":"陈瑩中画像赞 其一","f":"词","c":["凤阁鸾台何许，天涯地角周游。","此老老而益壮，超然一段风流。"]},{"t":"陈瑩中画像赞 其二","f":"词","c":["了了了时非了，非非非处何非。","要识此翁端的，试看笔下形仪。"]},{"t":"临江仙","f":"词","c":["有个头陀修苦行，头上头发毵毵。","身披一副醦裙衫。","紧缠双脚，苦苦要游南。","闻说度牒朝夕到，并除颔下髭髯。","钵中无粥住无庵。","摩登伽处，只恐却重参。"]},{"t":"渔家傲","f":"词","c":["慧眼舒光无不见。","尘中一一藏经卷。","闻说大千摊已遍。","门方便。","法轮尽向毫端转。","月挂烛笼知再见。","西方可履休回盼。","要与老岑同掣电。","酬所愿。","欣逢十二观音面。"]},{"t":"秋蝇","f":"五言古诗","c":["秋风快如刀，着木木欲折。","蕃鲜转凄凄，入眼无一悦。","青蝇独何为，飞鸣犹未灭。","造化本无私，尔生亦偶窃。","念方三伏中，日车午停辙。","下照人世间，何异红炉热。","劲鸟倦戢翼，狞兽喘吐舌。","惟人于此时，体懈剧疲薾。","虚堂幸可逃，枕簟随意设。","好睡边韶同，素懒稽康埒。","更此值清凉，酣寝谓须决。","双睫才欲交，汗肤遭尔齧。","营营不绝声，宛类谗口呐。","使我寝不安，欲息还复挈。","况如一箪贫，未能万钱歠。","园蔬荐脱粟，杯盘殊灭裂。","双箸才欲拈，咀嚼遭尔餮。","适从何处来，食饮污修洁。","使我味不甘，欲咽还复噎。","驱除付疲兵，祗足增跛蹩。","宜哉孙权弹，为尔情激切。","期望秋风回，一扫无馀孽。","偶此延朝昏，勿谓风不烈。","气候侵凝凛，龙蛇且藏穴。","尔形大豆然，岂能坚如铁。"]},{"t":"送李光道承事罢高邮酒官","f":"五言古诗","c":["豫章拂青冥，密荫覆百亩。","初由拱把微，封植岁月久。","大厦搜栋梁，匠者终见偶。","甘井如车轮，千寻彻坤厚。","畚锸非一朝，致力自培塿。","河流涸生尘，源源独清浏。","李子素绮纨，操约世莫诱。","字画尤劲奇，往往过虞柳。","当其求帖时，彷佛昔人呕。","吾惟蜩翼知，岂暇恤众口。","愿言举斯心，夙昔仁义薮。","甘井与豫章，勿使擅所有。"]},{"t":"送楼谦中赴江州德化主簿","f":"七言古诗","c":["忆昨随侍游鄞川，穷探欲上苍崖颠。","峥嵘古寺忽邂逅，眸子顾我惊瞭然。","子时苫块惨无意，挥麈岂暇论幽玄。","星离雨散已五载，谁谓此地方周旋。","胸中突兀富经史，欬唾落纸珠玑圆。","明明君王正侧席，何事版籍从拘挛。","匡庐胜槩半境内，足以寄傲追前贤。","穿云漱涧遍所历，妙句流落人间传。","却来隐几北窗下，博山深炷沉香烟。","细观身世究竟处，何者当好何当捐。","纷纷万事付一笑，聊复尔耳姑随缘。","吁嗟二轮挽莫住，愿子于此同勉旃。"]},{"t":"赠茅山范道人","f":"七言古诗","c":["道人本是红尘客，曾把锥刀闹胸臆。","一朝矫首看冥鸿，弃子捐妻人莫测。","三茅峰北华阳南，凌乱烟霞閟殊特。","筑庵寄傲知几年，但见日月忙如织。","饥餐落英饮沆瀣，策杖溪云随降陟。","蟾辉倒射松风寒，长啸一声山欲辟。","飘然行止信自由，或到人间蹑人迹。","朱门瓮牖初不分，遇酒辄倾论斗石。","有时巧发惊四筵，季主犹惭多失策。","纷纷流俗争称奇，岂识道人真所适。","茅君仙去空遗踪，高行三千当自积。","琴閒棋罢幸相过，却恐鸾飞无处觅。"]},{"t":"送宋司理赴吏部","f":"五言古诗","c":["古木暗长堤，清涟涨轻縠。","南风聒乌樯，动子归兴速。","今日共一樽，明朝各川陆。","我心久已灰，惨怆辄眉蹙。","鲍叔实我知，嵇康亦子熟。","少年挺奇姿，绮丽诱莫逐。","抑首掾雄藩，哀矜见推鞫。","季文每三思，石庆惧谴戮。","多事如不胜，投刀斯中族。","重华虽前旒，疏逖无隐伏。","杂遝登俊良，能官真棫朴。","行看万里涂，追电恣腾蹴。","赫赫继家声，勿忘勤圣读。"]},{"t":"登召伯斗野亭用孙莘老韵寄秀老参寥","f":"五言古诗","c":["广陵最佳处，堂与南山平。","慨然寄远瞩，溷浊为冰清。","冷官从无徒，犹阻窥朱甍。","矧兹斗野构，名实久已倾。","距我逾一舍，何由偕友生。","王事有邂逅，川途假新城。","登亭若为慰，饥渴甘大烹。","莲花袭襟裾，双鹤唳且行。","一笑发深省，坐见星斗明。","回首莫逆交，物外正采荣。"]},{"t":"寄楼谦中","f":"五言古诗","c":["三年客扬州，鄙吝谁与晤。","美人海上来，青眼独余顾。","荒凉吊遗踪，每每参杖屦。","败意无俗物，欣快平生遇。","陶丘今杜门，习懒殆成痼。","麈尾挂壁间，琴书自朝暮。","匡山正倚天，枕漱实幽趣。","清壮增茟力，重规谪仙句。","相望越千里，款段不获驱。","何当继畴昔，把手论情素。","惟有月下桐，秋声已如故。"]},{"t":"效十二属体","f":"七言古诗","c":["区区鼯鼠技不优，鼓刀要使无全牛。","力探虎穴必有获，纵如兔窟焉能谋。","好龙既久乃龙至，画蛇添足岂蛇侔。","骢马御史风烈在，瘦羊博士声名流。","棘端犹作刻猴用，宝鼎忽患烹鸡求。","相狗他年会见赏，牧豕海上非吾忧。"]},{"t":"感年","f":"五言古诗","c":["一世三十年，我今二十九。","昔人当此时，事业已不朽。","颜渊语心斋，瞠若夫子后。","著录盈三千，独居四科首。","荀彧王佐才，智略子房偶。","脱身作谋主，谈笑解纷纠。","元宾与习之，二李相左右。","复命索玄微，词章配韩柳。","夙成更超伦，初不愧黄耇。","项橐实可师，仲尼安敢友。","孔融登龙门，元礼接弥厚。","叔度千顷波，能使荀淑忸。","陈蕃置一室，誓涤天下垢。","贾谊入朝廷，号咷动明后。","陆机文赋成，见者咸敛手。","祢衡孰比俊，帝室宜见受。","李贺锦囊中，佳句敌琼玖。","相望编简上，灼灼列星斗。","而我独何人，拟之一无有。","追维故时事，浃背汗如浏。","穷年坐井底，曾不辨齑臼。","多岐既亡羊，画虎欲类狗。","狂澜傥不回，何以刷兹丑。","吁嗟岁律逝，易于屈伸肘。","分阴所当惜，来者勿复苟。","譬彼力田子，耘锄肯卤莽。","所期嘉苗成，不使乱于莠。","血气况方刚，龙钟未为叟。","高名非我心，没齿庶无咎。"]},{"t":"菏泽","f":"词","c":["滔天洚水非凡灾，平地汹汹生风雷。","帝尧哀民作鱼鳖，咨禹平之时懋哉。","未暇雍容堂陛上，和羹以尔为盐梅。","禹知休戚系予手，汲汲岂获怜婴孩。","疏凿高低捐四海，校量势力天须回。","尔时菏泽次第及，导引一股从东来。","就中不独豫州利，八荒赖以川原开。","农桑处处酬愿欲，鸟兽蹄迹还蓬莱。","此泽虽微与有力，揭之载籍悬星魁。","禹归上天已万祀，遗利犹今分九垓。","帝里虎士不知数，朝昏待哺张其腮。","转输粟布自东部，浃日何啻浮千桅。","始知寸胶无足用，安危须仗经纶才。","君不见黄河泛滥金堤摧，縻费皇家几亿财。","华衣肉食皆妙选，年年议论喧中台。"]},{"t":"陶丘","f":"七言古诗","c":["山河融结皆奇状，此丘之形谁与创。","一成为敦再为陶，二帝昌时已询访。","至今禹贡名字存，气势仍容菏泽傍。","普天率土此其中，杂遝舟车来四向。","分茅开国南面尊，屡致千金谢齐相。","尔来日月几春冬，兴废相寻人物上。","纷纷万事已尘埃，此丘迤逦初无恙。","平生苦死嗜登临，准拟携筇事疏放。","冷云寒日满荆榛，蕞尔令人重悽怆。","会须东走泰山颠，纵目乾坤更何障。"]},{"t":"默坐有感","f":"五言律诗","c":["后悔宁可追，称误岂容数。","试观古来人，何以为先觉。","一日三省躬，此事在力学。","年光捷霜蹄，我心羞龌龊。"]},{"t":"次韵罗正之提刑见寄","f":"七言古诗","c":["天边故人赠明月，恍惚如临沧海阔。","几年麈尾阻清谈，一日中肠宽百结。","钟君骨朽谁能琴，流水高山犹到今。","平生宫徵愧伯牙，邂逅夫子还知心。","相期端欲追前古，诸事斯言逃责数。","青云穷达岂须论，廊庙由来齐子午。"]},{"t":"王景亮携晁无咎清美堂记来求诗为赋此一篇","f":"七言古诗","c":["先生不出二十年，幅巾种树老卢泉。","卢泉水木清且妍，筑堂流水茂树间。","晁侯作记笔如椽，画栏素壁青瑶镌。","明珠白璧光射天，先生矜诧喜欲颠。","春归野岸绿漪涟，青山东缺如断环。","雪消风软山苍然，杏梢红破胭脂寒。","先生醉狂梦思山，自驾草车束尘编。","上堂读书门画关，金徽朱丝弄猗兰。","相思古人太古前，若非豪士鲁仲连。","即是幽人梁伯鸾，先生好学老益坚。","少时不信功名艰，青衫屡补履决穿。","晚知有命绝可怜，归来自买汶上田。","䆉稏香露凝秋殷，只知留客有酒钱。","肯问釜粥寒齑酸，拖金曳绣卷晓班。","何似布褐暖且宽，先生所愿一何廉。","贵人孰与先生贤，朱门铜臭厨肉膻。","夜阑白月照管弦，美人一笑夭桃燃。","安知贤达死丘园，正恐后世终无传。","此意已输先生先，我今欲归无由缘。","蕙帐依约闻清猿，何时相从一醉眠。","梨花杨柳傍禁烟，曾点浴沂春衣单。","德公渡沔应已还，山中桂枝聊攀援。"]},{"t":"三朡亭","f":"五言律诗","c":["结构安在哉，荒凉但郊薮。","无言对斜阳，庐儿亦搔首。","唯馀旧时春，年年暗榆柳。","弃置勿复论，兴衰古来有。"]},{"t":"成阳","f":"七言律诗","c":["茅茨土阶不图好，想见游宫滋草草。","有时警跸从天来，谇语应无路傍老。","可封之民纷万邦，岂独兹城知所保。","谷林南畔今如何，烟草茫茫车马道。"]},{"t":"范蠡冢","f":"五言古诗","c":["山栖尝胆时，祸胎久已孕。","欲令苏台倾，端俟天人应。","夫子实奇才，大事力能胜。","中分句践忧，内外各宜称。","一鼓雪前羞，功名在乘兴。","向非断以独，未必还千乘。","荆棘梗寒宫，晨朝露常凝。","可怜东门眼，至此不得瞪。","乌喙鲜克终，天道亦恶剩。","脱身海上来，嘉言谁与赠。","位高金更多，所向岂蹭蹬。","况有绝代姿，提携充妾媵。","试看剑头血，何如穷绝磴。","由来进退间，处之贵不懵。","孤坟忽生疑，文献良足證。","吴人未忘情，高楼时一凭。"]},{"t":"恭王殿","f":"五言古诗","c":["昔人语君臣，相须比弓矢。","乃若父子间，至情非所拟。","惟王适帝心，重以才艺美。","朝罢正临轩，隤丸未云已。","谁令羽翮摧，高飞为中止。","朅来天宇东，基构傍菏水。","灵光屹相望，应陋苟完矣。","于今崇传舍，便是当时阯。","那知王者居，日与行子市。","悲风起庭槐，飒飒盈双耳。"]},{"t":"送交代荣子邕","f":"五言古诗","c":["頖宫久戢身，所造益了了。","慷慨揖古人，百为无一矫。","就令力回天，初不变忽眇。","璀璨文字间，与此故相表。","服膺今十年，邂逅辱继绍。","遇我逾故交，微言几昏晓。","可怜不两留，行色逐飞鸟。","蓬山插青冥，郁郁佳气绕。","怀铅谢风尘，大用此其兆。","愿子更勉旃，真贤古来少。"]},{"t":"端午郊园","f":"五言古诗","c":["叔度久不见，我心如乱茅。","良辰适端午，万事聊一抛。","策马指圭窦，同焉有神交。","森森千亩竹，正尔清乐郊。","相与造其下，香泉荐嘉肴。","高谈落美玉，逸气腾长蛟。","径就真乐处，古音奏陶匏。","日车驻晴空，木杪疑焚巢。","何必蒲葵风，翛然涤惛怓。","兹游信物外，孰与娱云髾。","无端消息来，主人随钲铙。","会须更卜日，城府方胶胶。"]},{"t":"送黄元明赴梁县尉","f":"五言古诗","c":["豫章控江南，山高水沄沄。","钟此千里秀，君家贤弟昆。","文采映诸父，鸾凤争腾骞。","伯氏晚相遇，许我游其藩。","聪明置不用，道术臻忘言。","妥然稠人中，容貌白玉温。","求之古君子，端若李仲元。","一尉聊尔耳，谁识君所存。","霜风惨黄叶，雪雨埋朝暾。","柴车竟行哉，我心忧聋昏。"]},{"t":"次韵醇中见寄","f":"五言古诗","c":["此身风中蓬，飘飖洛西豪。","所向不胶漆，杜门天自高。","坐怀平生友，皎皎眉间毫。","书随鹊声来，厚我逾绨袍。","如何东野鸣，亦复追离骚。","彼苍久已均，后逸须先劳。","试看刀笔微，他日犹萧曹。","麴蘖正多事，要在餔其糟。","勿谓伯乐死，辕下终奇遭。","况乃掣电中，几许堪游遨。","展江涵清空，春光集渔舠。","命驾裁数驿，慰此心忉忉。","吕安何人斯，君首无徒搔。"]},{"t":"韩园","f":"五言古诗","c":["春风挽我出，邂逅陪友生。","滨湖足胜事，系马聊班荆。","疏柳傲清浅，孤芳媚晴明。","禽哢杂鱼跃，日转无人行。","此间已深趣，继踵仍高情。","犀局自胜负，玉轸谁亏成。","盈樽不在饮，会意时一倾。","岂减七贤游，亦云四者并。","如何渺茫外，忽起丝竹声。","未暇从尔为，目断陉山横。"]},{"t":"送宋子发节推","f":"五言古诗","c":["富贵如烈火，销铄谁为钢。","黄金攫清旦，一视无四旁。","夫子真璞玉，炎炎讵能伤。","万事有规矩，岂与时低昂。","五十犹幕府，鬓发初不霜。","天眼终自清，弹冠指明光。","卿云澹朝日，舞蹈萦炉香。","勿忧雨露隔，二圣方当阳。","大器故晚成，此去未易量。","巾车难更轫，潩水徒汤汤。"]},{"t":"次韵崔德符游湖","f":"五言古诗","c":["无双蔼嘉誉，夫子真黄香。","磥砢傲松桧，人间自炎凉。","平生翰墨中，赤增戏萧娘。","颍川今何时，鼓翼端来翔。","西湖谢尘土，危楼更斜阳。","幽期得高士，一笑歌沧浪。","新诗落圭璧，岂异连城偿。","胡为独缰锁，不作逢潇湘。","杖屦行清秋，从容酬所望。"]},{"t":"次德符湖光亭之什","f":"五言古诗","c":["平湖泛日月，清光渺无端。","并包入眼界，危构何轩轩。","轮蹄隘行路，逸步谁与攀。","只应空旷中，缥缈飞神仙。","我心本虚室，朝市成青山。","居然发馀照，妙用同一天。","凭栏岂无人，杯盘争击鲜。"]},{"t":"简德符","f":"五言古诗","c":["清标藐冰壶，一见涤袢暑。","况乃北窗风，穷辰荐佳语。","郑声正喧天，忽此闻柷敔。","坐令偕生疾，不得砭石去。","我愚虽绝人，志气肯为鼠。","如何城下盟，欣然为君举。","请看时雨来，润泽先柱础。","岂无力使然，默感自难阻。","高堂久悬榻，宝剑已心许。","昨宵共灯光，今作参商处。","秋意入梧桐，滴沥斗东序。","连墙莫至前，念君初逆旅。","蛇影勿狐疑，当思啖齑杵。","桑蓬元四方，事业在伊吕。","匪石讵可转，纷纷任儿女。","但愿早晴明，交臂无龃龉。","更约靖节君，相与富毫楮。","朝昏经史间，端知植禾黍。","他年羊子妻，焉能断机杼。","君席果不分，我知逃尔汝。"]},{"t":"用王宪韵寄参寥","f":"五言古诗","c":["天资不纷华，脱身礼白足。","一笑语曹溪，与世作眼目。","有时戏毛颖，新诗奴郑谷。","翘然百家中，疏烟澹脩竹。","顷年古招提，山青水澄渌。","倾盖揖孤标，令人惭逐逐。","平生稻粱谋，从此在鸿鹄。","尔来落高阳，辕下方局促。","况乃建隆师，黄垆已埋玉。","岂必阮步兵，途穷泫然哭。","赖君金石声，丁宁雁飞速。","我心端何如，盲龟得浮木。","遥闻玉堂老，初情敦夏屋。","支遁久尘埃，风流一朝续。","营营覆载间，万事风前烛。","愿言扫云窗，聊对传灯录。"]},{"t":"送张舜谐游上庠","f":"五言古诗","c":["高木纷万状，皆从毫末来。","天时与人事，相资以为媒。","根本初不同，他时终异材。","东风动霄壤，繁华媚池台。","花枝竟无言，车马争徘徊。","霜雪一朝怒，孰与松柏陪。","青青几千尺，寒峰正崔嵬。","向来丝竹处，索寞空尘埃。","明堂屹南面，梁栋支倾摧。","匠石有青眼，肯为桃李开。","穷年后悔心，何似今日回。"]},{"t":"颖桥僧舍壁间有诗颇怨不遇因次其韵刺之","f":"五言古诗","c":["食肝何必马，食鱼何必鲂。","趣操苟冰炭，谁能屈邹阳。","人间所荣观，金门与玉堂。","患失纷鄙夫，白首犹悢悢。","岂识君子心，草衣如绣裳。","薮泽方尉罗，鹪鹏已翱翔。"]},{"t":"路傍草","f":"五言古诗","c":["洪造初无私，物自生殊异。","丛丛路傍草，枝叶一何悴。","行人或陵践，牛羊肆残毁。","纵能胜疾风，厥害还遭值。","瞻彼山中兰，孤芳常茂遂。","馨香动君子，采撷远而至。","须知得失间，所托惟其地。","呜呼儒衣冠，如何不尚志。"]},{"t":"午枕有感","f":"五言古诗","c":["宰我嗜昼寝，边韶仍爱眠。","当时师弟子，指摘良纷然。","韦弦以为戒，僶俛亦有年。","分作蠹书鱼，文字相周旋。","纵不叔夜懒，犹惭头在悬。","如何到此地，午枕有所便。","晨餐未停箸，睡思潜予牵。","矇眬眼自醉，百体柔于绵。","茗饮虽再三，驱逐无由缘。","解衣卧北窗，径走姬旦前。","往往随物化，飞跃参鱼鸢。","老木森古砌，日转惊鸣蝉。","矍然整巾屦，衙鼓忽已传。","由来棘围中，疏放成拘挛。","气血似止水，郁郁为此愆。","何当彻门牡，四顾还青天。","朝昏递消息，有节亦有宣。","焚膏续清昼，冥心寄韦编。","往失固莫救，尚得来者全。","圣处几万里，行矣勤着鞭。"]},{"t":"次韵邓州范仲成秘校见寄","f":"七言古诗","c":["落笔文章真宋玉，八面纵横欺炙毂。","潜藏头角卧南阳，刖足岂是王骀辱。","每嗟愚贾谩操金，他日辛勤只书簏。","丈夫事业会惊人，谁知范叔成张禄。","相逢怜我再齑盐，不羡高门厌粱肉。","追惟吴国旧时踪，山澹晴烟水输渌。","几年嵇阮作参商，漠漠茂林空自竹。","欢然一笑换凄凉，端遇牛公容杜牧。","尔来日月更中天，未应寂寞餐秋菊。"]},{"t":"用前韵寄邓帅杜君章学士","f":"七言古诗","c":["策府名卿厌鸣玉，朅来南阳朱两毂。","胸中云梦吞八九，终然不贮闲荣辱。","坐令政事邈前人，容易端如探筐簏。","去年持刃今扶犁，所至熙熙丰谷禄。","华堂梦断燕丝簧，笑谓邹枚不如肉。","公虽饮少客自醉，但见银瓶倒轻渌。","明明天子正搜贤，真贤继踵还符竹。","勋劳矧已疏屏风，八命难淹一州牧。","愿公快向百花洲，更集宾僚勤把菊。"]},{"t":"用前韵寄穰城谢公静推官","f":"七言古诗","c":["邂逅蒹葭来倚玉，浅见惭如视车毂。","荷君倾倒过平生，妙处令人忘宠辱。","并包今古入灵台，欬唾珠玑几盈簏。","纷纷年少多公卿，何独斯人犹寸禄。","南阳刺史今伯乐，叹息龙媒异凡肉。","剡章求以助风流，岂减红莲汎澄渌。","更将馀力付蟠根，迎刃无留真破竹。","才全如此帝未知，燕閒却自思颇牧。","东山出处是家风，莫学渊明恋私菊。"]},{"t":"范仲成约非晚过颖昌留数日因邓兵还追用前韵寄之","f":"七言古诗","c":["勿叹卞和犹抱玉，勿嘲扬雄未丹毂。","由来识拔须待时，阨穷不是男儿辱。","相逢相别竟匆匆，赖有好诗藏敝簏。","居然成诵想英标，杀马无因愧持禄。","还家青镜览形容，鞍上岂徒消髀肉。","故人要我泛西湖，万顷瀰漫浸天渌。","坐中寂寞欠车公，只应冒雪歌黄竹。","从今尘榻扫南窗，日俟高车起耕牧。","悬知乐事与众分，把盏追论灯下菊。"]},{"t":"与王仲弓分韵得东字","f":"五言古诗","c":["西豪星聚时，有客还頖宫。","解骖听挥麈，落落凌霜风。","平子素我厚，缪入题品中。","夷甫不复言，目系心已同。","埙篪竞远韵，欣逢吾道东。","平生仰高山，鹄立拘樊笼。","谁令燕雀微，一旦追冥鸿。","明珠继来投，照夜惊儿童。","从今日虚徐，所冀资磨砻。","只恐天池鲲，朝夕抟晴空。"]},{"t":"次韵仲弓见赠","f":"五言古诗","c":["我生分稽古，未始怀宴安。","万事不入眼，人间自悲欢。","独于文会时，所取良必端。","起废赖发药，他年逃素餐。","苏君日千里，逸步逾飞翰。","一从断金来，况也宁永叹。","于今更天诱，还逢鲁圆冠。","倾盖如旧识，礼法能见宽。","须知高门闾，阶庭富芝兰。","何独仲弓家，弟兄称二难。","琴张诚可友，愿言谢外观。","圣域渺无旁，观水须观澜。"]},{"t":"送裴仲孺摄汝阴尉","f":"词","c":["我读醉翁思颍诗，恨不六翮西南飞。","頖宫朅来滨颍水，颍水虽同非颍尾。","羡君匹马秋风前，吏隐去作南昌仙。","霜威凛凛肃普天，环湖潇洒皆当年。","时丰铙鼓如寒蝉，想见丝缗上钓船。","太白还光醉翁死，邻家仍无隐君子。","山高水深谁与知，只恐未乐君先悲。","朱方豪士森戈矛，青云蹭蹬犹督邮，不如黄鸡白酒相与醉即休。"]},{"t":"次韵世美游嵩山","f":"五言古诗","c":["肇分五岳尊，上帝委奇石。","维嵩据地中，屹立万仞壁。","远与四镇殊，式应土圭测。","有人仰崇高，坐厌拘名迹。","邂逅天际来，骅骝脱车轭。","将圣祭泰山，此心岂悬隔。","扰扰尘土中，一朝复一夕。","闻君有风期，欣然双蜡屐。","焉知马足非，迥隔千峰碧。","古人亦多端，相望托幽寂。","法音动山灵，松栝惟所适。","寄径登显途，自恃捷无敌。","遗辙谅未泯，一一可游历。","借问去来人，谁堪比心迹。"]},{"t":"送崔子厚朝散倅安州","f":"五言古诗","c":["君家如武库，人物常森森。","伯氏妙难测，一笑冥古今。","蒲团与藜杖，终然作知音。","王事挽以去，岁杪霜雪侵。","轻轩奉白发，遥指甑山岑。","臣子难有已，忠孝亦已深。","南方拥兵刃，调发多呻吟。","使民还击壤，屏星实分任。","况乃功业本，从来在无心。","独恨锁天北，谁与同瑶琴。"]},{"t":"次韵仲弓见怀","f":"五言律诗","c":["与子风雨散，掩关非世喧。","琴书到古人，危坐屡忘言。","何当同此趣，脱略文物繁。","岁晏犹清居，厉节真王尊。"]},{"t":"悼陈生","f":"楚辞体","c":["豪商破浪随东风，辘轳相继沧溟中。","回环极目渺无际，万石之载裁飘蓬。","一朝六鹢不得进，十舟八九成虚空。","一舟邂逅脱鱼腹，开帆岂暇论西东。","大明出没夜复旦，何许清越鸣晨钟。","舟人侧耳正惊喜，忽瞻水际排奇峰。","落帆沉碇泊古岸，介然荒径云间通。","鄞川书生托舟尾，见之踊跃追猿狨。","扶疏怪木进十里，突兀古院题天宫。","入门长廊转寂寂，堂上高拱厖眉翁。","左右侍立满三百，谈玄演义声玲珑。","相逢问劳悯流落，旋启虚室栖行踪。","纷纷袍布欺腊雪，独此锦帐朝霞红。","黄金白玉荐丰馔，药苗蔬甲青茸茸。","主翁自言避巢寇，朅来不与中原同。","于今天子果谁氏，语罢默默如盲聋。","日遣二子共游处，因得细诘开冥蒙。","皆云我辈号处士，名字非列神仙宗。","三等三百奉一主，上等第一裴休公。","提携峻陟几千丈，笑秦亭上聊从容。","秦皇可笑笑不已，声撼亭角摧穹隆。","徐福曼倩亦何在，前后石壁犹房栊。","举头指似蓬莱岛，霜雪直上磨苍穹。","波涛作势撞山脚，鲁有神圣躬磨砻。","欲令异物知所畏，周遭水面盘蛟龙。","书生名利浃肌骨，尘念日久生心胸。","老翁照见辄微笑，血盆再入宁易攻。","蓬莱有路尔常睹，此别旷劫无由逢。","吾今舟楫助尔往，尔其登览庶可穷。","日轮迎晓傍山出，水声先沸惊寷窿。","赤光散合动天地，顷刻气候分春冬。","高低殿角屹相向，一一镌凿非人工。","穷晨不复值仙子，卿云瑞雾空蒙茏。","询之处士盖有谓，近世人迹几相重。","鸾骖鹤驭厌凡肉，矫然远举归鸿濛。","先生吕翁独于此，一年三四眠松风。","书生尘念竟不断，主翁但问何所供。","人参如人更长大，愿乞数本扶疲癃。","翁言此物有神护，特经海道须罹凶。","良金美玉亦至宝，尔诚欲之吾当从。","慇勤教告岂一事，尤戒卧语详初终。","楞严秘密偈四句，奉以周旋宜恪恭。","书生再拜起沉碇，转盼已入鄞州封。","还家妻子久黄壤，单形只影反匆匆。","却思投翁事清净，天南天北惟飞鸿。","茫然进退真捕景，一生颠倒终狂童。","君不见秦皇汉武操利势，自许神仙力能致。","海边方士日从横，毕竟千非无一是。","书生径步蓬莱巅，况乃天人勤指示。","若为名宦苦死坚，失脚青云坠平地。","仙兮仙兮一何异，求不求兮两莫遂。","我虽忘情亦欷歔，仲尼之门非所议，率然作诗纪其事。"]},{"t":"次韵世美冬夜见怀","f":"七言古诗","c":["君家儒学频公侯，岂知孔孟穷于邹。","他年事业知未艾，诜诜孙子多清流。","红莲上客更超诣，劲节耻与今人俦。","自言名宦亦何有，回看家法长包羞。","芜城岁月已波逝，朅来文会消吾忧。","青天白日有崔子，亦许交臂闻嘉谋。","人生南北那可必，合散倏忽春云浮。","会须着鞭入圣域，无使后悔空冥搜。"]},{"t":"送德符还阳翟并简陈叔易","f":"五言古诗","c":["霜严识苍柏，火烈知黄金。","不有小人谤，孰窥君子心。","前程已如此，纷纷矧于今。","衡门杜朝夕，巧舌犹追寻。","一与接为构，何以逃交侵。","任大始多事，由来天意深。","北风动秋夜，兴落西山岑。","逸驾岂受挽，耿耿聊分襟。","太丘阻眉宇，为我先寄音。","渔父可师否，兹焉共浮沉。"]},{"t":"烹密云龙","f":"词","c":["君不见子建七步俄一诗，太冲十年仅三赋。","相去何啻楚与越，尔来题品皆才具。","我生尚友到古人，袖手寒窗重惭惧。","巧迟拙速非所长，舟溯湍流只如故。","秋风逸思谁肯分，惟资茗饮祛昏瞀。","人间气味足奇功，毕竟不能成好句。","集仙公子天上回，拭目元丰新制度。","夜光明月岂足珍，矫矫真龙翳云雾。","潜藏飞跃自有时，只恐缄縢终不固。","况闻醉翁归颍东，更号六一逃机务。","震霆端的助滂沱，名称恰应当年数。","从今掩卷待青禽，晴轩屑玉和甘露。","胸中无复旧尘埃，五物狂吟在朝暮。","须知料虎戚自贻，莫讥恶客君家蠹。"]},{"t":"次韵苏子骏寄其弟世美","f":"五言古诗","c":["霜风战芜城，耿耿袖间手。","峨冠何许来，逸气蟠九有。","入眼无可人，终焉收下走。","舌端写天河，那知胆非斗。","离亭巧梯媒，节物几榆柳。","所向曹匼阿，刚肠欲雷吼。","饥寒挽柴车，莫获亲可否。","年来但韦编，妙处知不朽。","规模绵古今，元自一布肘。","翛然环堵中，未觉羲皇久。","三复鹡鸰诗，亦已等妍丑。","此心千里同，岂愧鼻如口。","更闻隐君子，随风落岩薮。","崇朝公事休，嗜好斥杯酒。","幅巾款玄谈，聪明谢天诱。","万象悬目前，轩豁开户牖。","坐令黄堂上，观净亦成垢。","维皇急亲贤，承庸拔师友。","丘壑难自娱，岩廊拱文母。","只恐行赐环，仙去误鸡狗。","与其羡长生，孰若寿黔首。","一语君试听，黄梅未当剖。"]},{"t":"靖节堂分题得重字","f":"五言古诗","c":["儒衣隘绵区，冰炭非一种。","邂逅心事同，清标揖孤耸。","驾言仁义涂，相与戒前从。","廓廓膺肺间，何由纳天宠。","春风入高堂，文字竞拳勇。","妙句窥杜陵，微语倾叔重。","翘然真四夔，吾道有扶拥。","遂令斥鴳姿，端为钟鼓悚。","从今日喧妍，胜处宜接踵。","独恨韩城君，伶俜泣新垄。"]},{"t":"次韵崔光先见简作诗催春色","f":"七言古诗","c":["春游有客忘朝暮，酷似经星好风雨。","岂知仲蔚长蓬蒿，寂寂儒宫裁一亩。","新诗故委黄耳来，舌在惊疑为频吐。","鸿钧觅运扫辙踪，万物终然归鼓舞。","去年枯槁欲樵苏，今已蕃鲜媚农圃。","我家吹律信参天，苗裔非才阒无睹。","族寒官冷自离奇，安能仰赞娲皇补。","庙堂燮理皆少年，伫见囊金罄花坞。"]},{"t":"送幼安赴澶仓","f":"五言古诗","c":["人生本逆旅，行止良悠悠。","试看康庄上，辙迹多成沟。","公子分闭户，时来亦何由。","载书晓遄迈，春令方如秋。","河滨古城府，税鞅聊优游。","青云捷径在，坻庾非君优。","臧孙故有后，崭崭承风流。","胡为重作恶，日暮犹登楼。"]},{"t":"仲儒烹密云龙得烹字","f":"五言古诗","c":["清都密云龙，遐方久驰名。","无因饮天赐，叹息非公卿。","尔来牛斗间，瑞气蟠纵横。","龟书识至宝，近在璧假城。","物色到君箧，发视凡骨惊。","君心本铁石，从此亦变更。","自言匹夫耳，乃有怀玉声。","群嘲杜潜隙，径约良友烹。","伊予岂其人，重以慰平生。","可怜谢康乐，新诗徒尔鸣。"]},{"t":"鲜于大受蜕轩","f":"五言古诗","c":["斲轮知读书，解牛知养生。","天下一致耳，冰泮无馀情。","向来所筌蹄，俄已蜩甲轻。","岂必吟泽畔，始为当世清。","鲁堂殆庶几，居然黜聪明。","蠢蠢冠屦间，胸中妙难名。","鼓铸虽有自，竟脱模范成。","诗翁既迁去，委蜕今韩城。","闭门作龙蛰，端俟风雷惊。","文史聊寄径，与古将抗衡。","何以识此心，标榜辉前楹。","他年付卷舒，会见推善鸣。","应怜刘季陵，寂寞初无声。"]},{"t":"送郑祭酒得宫观还乡","f":"七言古诗","c":["闽中男子多儒衣，龙骧虎视惟四夔。","门前蓬藋老风雨，籍籍声名天下驰。","尔来半作古人去，亦或霜鬓甘伏雌。","独随日月上星斗，即今先生侍丹墀。","先生胸次真武库，无所不有世莫窥。","早年剖符勤抚字，晚年赐环妙论思。","朝廷远览得治本，务先长育英豪姿。","凌云大厦岂一木，要在钜细皆其宜。","先生彬彬揭模楷，仰膺帝可端为师。","鸾飞凤举遍台阁，辟雍祭酒终不移。","下帷庄坐对沉燎，诸生自耻专浮词。","斯文与天共澄霁，肃驾圣域无多岐。","他时合抱挽梁栋，论功较德谁高卑。","先生胡不长风宪，豺狼在念略狐狸。","坐令饮恨深发喜，簪缨无复藏奸欺。","先生胡不同翰墨，形容尧仁晓天涯。","鲁官典诰从此复，大哉王言非寄私。","先生胡不秉枢极，以道揆事如蓍龟。","河防民役有定论，简拔贤俊去嫌疑。","吏员一一底乃绩，二虏拜手受指撝。","东西南北几万里，匹夫匹妇违寒饥。","人言太平亦无象，但见父老同儿嬉。","胡为五湖入清梦，忽焉幽兴落武夷。","千钧一发谁挽得，径约赤松歌紫芝。","长安车马竞回首，颇似巨源辞位时。","通德高门想如昨，溪风旦暮犹有期。","冷然杖屦远俗物，此心惟许江鸥知。","巍巍北辰拱天子，还淳直欲跻皇羲。","人才未登常侧席，鹤书每每空山茨。","金瓯况复旧名氏，只恐先生难自怡。"]},{"t":"元鲁侍亲还以凡今之人莫如兄弟赋诗送之 其一","f":"五言律诗","c":["秋风卷轻帷，似送东归帆。","亲心为恻恻，谷马驰两衔。","吴江渺清冷，吴山郁巉岩。","侍行不尔俱，官曹犹治凡。"]},{"t":"元鲁侍亲还以凡今之人莫如兄弟赋诗送之 其二","f":"五言律诗","c":["北去青山门，宰木行森森。","吾祖不可见，岁月成古今。","侍亲奠鸡酒，应慰久客心。","尔心故自慰，尔兄涕沾襟。"]},{"t":"元鲁侍亲还以凡今之人莫如兄弟赋诗送之 其三","f":"五言律诗","c":["尔生见天地，较我两岁迟。","儿童作壮夫，恍若旦暮期。","诗礼久服膺，飞鸣当及时。","慎勿醉乡去，志士良耻之。"]},{"t":"元鲁侍亲还以凡今之人莫如兄弟赋诗送之 其四","f":"五言律诗","c":["姑苏一都会，井径分龙鳞。","风俗如郓城，臧否朝朝新。","况尔随侍子，动与嫌疑邻。","延笃傥可师，不如陪古人。"]},{"t":"元鲁侍亲还以凡今之人莫如兄弟赋诗送之 其五","f":"五言律诗","c":["至远挽不来，庭竹屡陨箨。","剖鱼得素书，颇说甘寂寞。","矫枉勿过正，执中思子莫。","他年同我心，俯仰无愧怍。"]},{"t":"元鲁侍亲还以凡今之人莫如兄弟赋诗送之 其六","f":"五言律诗","c":["至虚走桥门，所乐在群居。","群居固可乐，他途亦纷如。","合抱自毫末，要须慎其初。","大带有馀否，此语当急书。"]},{"t":"元鲁侍亲还以凡今之人莫如兄弟赋诗送之 其七","f":"五言律诗","c":["詹何我师友，文行悬高名。","天命岂易度，栖迟尚柴荆。","省定馀白昼，相与发大鸣。","才进非故吾，从此难为兄。"]},{"t":"元鲁侍亲还以凡今之人莫如兄弟赋诗送之 其八","f":"五言律诗","c":["四人如四支，阙一不成体。","故为各天涯，阻异晨昏礼。","但愿器业成，高阳亦兄弟。","此意何时穷，颍川方瀰瀰。"]},{"t":"次韵德符夜访世美","f":"五言古诗","c":["苏子甫及瓜，装赍动檐楹。","念此不数见，柴门行昼扃。","幅巾策藜杖，邂逅诸友生。","凉月委新照，无烦聚飞萤。","欢然造空洞，却顾轻簪缨。","齑盐未果腹，饱德如楚萍。","只应他夕来，矫首心盈盈。"]},{"t":"次韵樗年见简","f":"五言古诗","c":["一身能几何，首尾复自畏。","岂知尘表姿，落落惟所值。","官摛忽相逢，欣悲十年事。","须知袭人间，舒卷在毋意。","他时况英声，曾冠通侯次。","行矣方坦途，真贤不难继。"]},{"t":"用前韵寄乡中诸长者","f":"五言古诗","c":["乡邦蔼儒冠，后生良可畏。","况乃领袖贤，疑与古人值。","尔来索吾居，南北几岁事。","冥鸿云外心，疲马风前意。","遥知松菊间，青编焕鳞次。","何当返柴车，故步欢然继。"]},{"t":"次韵德符过曾园 其一","f":"五言古诗","c":["东方澹残星，车马各有之。","心落声利间，摇摇无静时。","幽人独朝彻，蟾光濯涟漪。","赋诗鸥鹭边，妙绝中郎词。","青时正相向，白驹忽已驰。","归来过我谈，闻风徒振衣。"]},{"t":"次韵德符过曾园 其二","f":"五言古诗","c":["数子清玉峙，粲粲凌朝辉。","持竿谢高风，钵囊聊自携。","岂不一趣尚，因缘非兔丝。","北去得幽圃，相与无町畦。","白鸟亦忘我，共此天然姿。","只应太史奏，还在颍水涯。","九原审难作，幸及同襟期。"]},{"t":"次韵仲孺见督烹小团","f":"五言古诗","c":["世事多好还，往躅端可视。","崟岩辉奇功，颇愧文王肆。","他年焚舟来，几作涂炭坠。","驷马岂及追，我今亦如是。","狂言编虎须，得报逾掐鼻。","平生储春芽，美恶初一意。","浊氛腾墨云，君舌故历试。","小龙落几前，毕竟不知异。","方欲事烹煎，姜盐以为使。","赖君呼回头，丝桐识秋思。","会当扫南轩，石铫沃清泚。","从此师金人，三缄诚有味。"]},{"t":"再酬仲孺","f":"五言古诗","c":["龙团方启封，数子已惊视。","端如肖壁人，骑羊入城肆。","又如金谷姿，不合楼前坠。","囊衣本酸寒，茶具无一是。","纷纷诘邻家，浪欲学拥鼻。","秋空辄云雷，秘惜乃天意。","未敢还巾车，且集诸生试。","岂非今年芽，岁月与君异。","直须如印刓，诗驿趼来使。","念君才患多，落笔有馀思。","盈编故可期，河流几时泚。","君应嘲马肝，不食亦知味。"]},{"t":"仲孺督烹小团既而非真物也怅然次韵以谢不敏","f":"五言古诗","c":["情伪初难分，饱闻不如视。","君看求马时，安得走唐肆。","此茶亦先声，入手恐失坠。","泠然风御还，共饮乃非是。","坐令竹边心，追悔如刻鼻。","故人岂欺予，姑以将远意。","由来毁誉间，夫子犹必试。","八床志多金，龙断何足异。","胡为不三思，取信輶轩使。","超超莆阳公，铨量妙清思。","仰止一喟然，背浃欲流泚。","尚赖君诗存，高吟忘肉味。"]},{"t":"戏世美","f":"七言古诗","c":["杨家绝艺十六弦，公卿往往趋宾筵。","妙龄才子更豪酌，月中醉倒西湖船。","楚宫残梦几春晓，五陵好事犹喧传。","只今展江尝托足，香风带恨留苔钱。","谁令故人不他寓，朅来亭上仍秋天。","幽花脉脉鉴清潩，似与当日争蚩妍。","此心如水亦滉漾，那堪釬拨还锵然。","骅骝夜半解归镫，青灯烱烱空韦编。","砧声渔唱起何许，坐久波面生寒烟。","故应鸥鹭有深意，忽焉鼓趐鸣窗前。"]},{"t":"十六夜府会湖光亭呈世美","f":"七言古诗","c":["使君终宴先归休，菱盘藻带妨移舟。","湖边何处月已到，观音堂下寒光浮。","鼎来谈笑托新兴，沉沉万籁乾坤幽。","云端飞翼弄清霭，波间戏鬣吹轻沤。","凉飙袭尘了无迹，似动不动蒹葭洲。","却观落日倚栏处，天东缥缈横高楼。","不须要月共形影，吾曹兹焉成献酬。","单衣盈露坐忘返，亦忘佳客相与留。","始知人世恶尘土，生平今夕方中秋。","昨宵莲社二三子，借问赏心如此不。"]},{"t":"次韵德符访世美","f":"五言古诗","c":["秋晨饭香积，举袂清风生。","朅来展江道，老木森亭亭。","纤埃不随步，昨宵寒露零。","人境两相值，简编焕新晴。","迁固久黄壤，椽笔窥群英。","崔子独异趣，一笑铅椠轻。","诗成似金籥，为我开尘扃。"]},{"t":"敬读仁祖实录用前韵","f":"五言古诗","c":["嘉祐纪庚子，犬马初冬生。","安知拱尧舜，不事沉香亭。","尔来百寮底，霏霏清涕零。","弓剑谁与问，白云飞晚晴。","恭闻语乾造，凛如班集英。","遗恩泰山重，死报鸿毛轻。","圣孙王纂承，行当叩天扃。"]},{"t":"送杜君童学士赴阙","f":"七言古诗","c":["西风猎猎鸣旌旗，南阳学士趋丹墀。","南阳父老挽不住，家声复如东汉时。","堂堂材具中梁栋，鬓边寒暑惊驹驰。","垂衣继照揭日月，只应一见舒尧眉。","鸾台凤阁有新路，着鞭宁许驽骀知。","委身报国一心耳，嶷如嵩岱谁能移。","他时廷尉妙生死，还将此道供论思。","凌云大厦肃天宇，千秋万岁无倾攲。","焦头烂额岂足尚，长堤蚁穴今图之。","回看蹇浅丈夫子，攫金清旦方沉迷。","矢来无乡亦可恤，付与公议分高卑。","前人得失焕清简，纳公胸次无孑遗。","愿言朝退坐华省，更以反己为元龟。","儒冠往往喙三尺，勿令白玉生瑕疵。"]},{"t":"世美归侍政府以送君南浦伤如之何作诗送之 其一","f":"五言律诗","c":["汎汎莲花池，日月几宾送。","乳燕辞故窠，征途亦飞鞚。","会合安可常，万事惊残梦。","何以宽我愁，风流在民众。"]},{"t":"世美归侍政府以送君南浦伤如之何作诗送之 其二","f":"五言律诗","c":["妙年公卿子，可人逢此君。","退然数尺耳，气节凌青云。","从今奉亲暇，简策陪朝曛。","应怜四杰流，勤勤但空文。"]},{"t":"世美归侍政府以送君南浦伤如之何作诗送之 其三","f":"五言律诗","c":["岩廊拱真人，妙与天地参。","政教似寒暑，岂罪樵夫谈。","木铎久不振，相府方潭潭。","公子饱见闻，归献北斗南。"]},{"t":"世美归侍政府以送君南浦伤如之何作诗送之 其四","f":"五言律诗","c":["忠孝非两心，事君如事父。","事君贵以人，事父孰为愈。","真贤绝骅骝，骨相未易取。","愿子继法真，毋令老江浦。"]},{"t":"世美归侍政府以送君南浦伤如之何作诗送之 其五","f":"五言律诗","c":["前年可罗雀，朱幡出濠梁。","今年可炙手，衮衣登庙堂。","公家本金玉，何曾变炎凉。","公子不展眉，端为斯人伤。"]},{"t":"世美归侍政府以送君南浦伤如之何作诗送之 其六","f":"五言律诗","c":["卞氏称六龙，公家宛相如。","久作风雨散，于今共诗书。","山前犹制锦，江上方题舆。","遥想侍侧心，夙夕雁与鱼。"]},{"t":"世美归侍政府以送君南浦伤如之何作诗送之 其七","f":"五言律诗","c":["犹子知几人，子独欣白眉。","风霆破春晓，怒翼鸣天池。","未促南昌行，还为竹间期。","傥及马伏波，一书重示之。"]},{"t":"世美归侍政府以送君南浦伤如之何作诗送之 其八","f":"五言律诗","c":["芜城兆霜雪，颍川凋芰荷。","昔别情已矣，今别情奈何。","英英二三子，行亦车悬■。","后日知谁同，蝉声犹暮多。"]},{"t":"送杜堪才以江汉故人少为韵 其一","f":"五言律诗","c":["与君本南北，作吏同一邦。","诗书雅相好，旨酒空盈缸。","岁晏赋归去，冉冉车轮双。","我亦非匏瓜，兹焉念松江。"]},{"t":"送杜堪才以江汉故人少为韵 其二","f":"五言律诗","c":["杜陵世多人，风流自唐汉。","振衣入朝廷，玉立争璀璨。","若人独何为，辕下尚羁绊。","舌在且加餐，慎勿发长叹。"]},{"t":"送杜堪才以江汉故人少为韵 其三","f":"五言律诗","c":["秋来几何时，送远惊已屡。","山川澹无情，苍莽亦非故。","分与人迹疏，韦编对香雾。","只应知此心，西陂有鸥鹭。"]},{"t":"送杜堪才以江汉故人少为韵 其四","f":"五言律诗","c":["青衫勿自少，委质皆王臣。","贵贱物外耳，直道惟其人。","下惠信先觉，到今如北辰。","居閒傥未能，君志终当伸。"]},{"t":"送杜堪才以江汉故人少为韵 其五","f":"五言律诗","c":["汉水方涸流，梁园正秋杪。","驾言托朝昏，陈事有台沼。","他年李杜来，慷慨识者少。","安得从君游，一笑今古了。"]},{"t":"马叔宝寄种竹诗次其韵","f":"五言古诗","c":["穷年不挥斧，叹息无妙质。","谁知深眇中，环堵以为室。","纷笔如万牛，力挽未曾出。","论交馀此君，聊为拂巾栉。","人间方好竽，萧萧乃鸣瑟。","兹焉得所投，陈雷信难匹。","昨来面墙心，举倡有风日。","莫似白乐天，殷勤在兜率。"]},{"t":"雪中对竹","f":"五言古诗","c":["飞雪一何情，拜我南轩竹。","骈头控于地，默默隃信宿。","寒花本轻扬，丛集乃折轴。","况此梢云姿，萧然异凡木。","飘风亦狂生，端来助陵蹴。","似欲揉直柯，绕指惟所欲。","焉知天与刚，初不愧幽独。","罄折虽尔为，且异望尘辱。","晨光破沈阴，春色盈两目。","风雪安在哉，竹犹故时玉。"]},{"t":"次韵韩君表雪中感怀","f":"五言古诗","c":["龙衣不解颜，忧民向来急。","天高委真符，年丰兆原隰。","连山水气昏，过云雁声涩。","先春凌马奔，投隙作尘入。","濒竹乍萧萧，惊风还汲汲。","颇轻花斗狂，肯共雨争湿。","夜半回晓光，木杪森鹄立。","开编适吾心，鼓枻辍清集。","一饱傥可偿，万事非所及。","想见秋稼前，腰镰荷青笠。"]},{"t":"用前韵寄德符","f":"五言古诗","c":["叩门无季心，尔来空缓急。","若人作枯蓬，随风落遥隰。","袖书珠玉昏，匣剑蛟龙涩。","雪花陵春阳，山寒拥扉入。","孤松初自高，短绠岂易汲。","伊予不逢年，所向惊束湿。","分携忽岁迁，结念成骨立。","萧萧清潩滨，冉冉白鸥集。","盟好何当寻，瓜时亦云及。","东游傥未忘，芦边一渔笠。"]},{"t":"次韵仲孺梦与世美诸友同集","f":"五言古诗","c":["箪食凄穷阎，綵衣焕华屋。","公子谢群居，几年羊胛熟。","逢迎纷故人，趣异终疑独。","精诚洞虚无，相应比如竹。","不羡春风前，流莺啭乔木。","勤勤通昔心，全胜书一束。","胡然亦神游，邂逅同梦鹿。","夜旦环中来，梦觉更主仆。","只今所见闻，转手惊莫复。","冰释倘未能，兹焉良可烛。"]},{"t":"次韵和韩大资湖光亭对雪之什","f":"五言古诗","c":["岩廊未旋归，故国聊自晦。","尘表澹崧高，胸中妙天对。","丰年随政还，嘉雪遍境内。","从容陟九层，指顾纷百态。","经纶动初心，枯槁入长嘅。","虽陈北海樽，终念东皋耒。","只应沙路乾，依前符帝赉。"]},{"t":"送曾仲敷赴庆州司户","f":"七言古诗","c":["栖迟颍水无三年，四见长途事鞍马。","问君胡为乐驱驰，告我吾非苟然者。","向来庭闱故当尔，今乃从知古塞下。","男儿出腹在四方，龊龊南窗吾未暇。","只手扛鼎非吾力，百步穿杨非吾射。","眇然躯干仅数尺，智略岂分子房亚。","诗书礼乐工作谋，元帅轩轩更儒雅。","相知不与今人同，往游其藩跃如也。","君言慷慨得我惊，我有私忧为君写。","巍巍法座天中央，万物生成得陶冶。","边尘吹风不见人，麟凤犹阻游郊野。","烦将此意问元帅，何当铁甲悬高架。","君家一唯如雷霆，震动乾坤失聋哑。","愿回庐阜异时心，白刃前头荐潇洒。","家风欻从千古还，上策酬恩真土苴。","口终拂袖两无言，因送飞鸿不知夜。"]},{"t":"次韵仲孺见怀十二韵","f":"五言古诗","c":["江梅飞故枝，桃李日夕更。","宰物初无心，芳菲自奔竞。","幽禽衔真如，历历唤不醒。","东里似得之，与春忘谒请。","颓然蘧庐中，槃薄天地永。","交情海沤发，吟兴秋翮劲。","璀璨十二旒，陶谢不获骋。","须知云气蒸，未害山石硬。","但君已追风，顾我犹蹇乘。","试冯作诗光，普照万物盛。","物尽照亦空，何许开绝景。","他时从此来，一眄躐千圣。"]},{"t":"次韵世美见寄","f":"词","c":["鼻端漫故蝇，心与天地远。","声容天地前，长似西湖晚。","判合亦何常，从古车轮转。","君不见儒衣壤壤趋白头，几人管鲍情相收。","我岂季子难之邹，行矣同听黄栗留。"]},{"t":"与仲孺破兔饼色味皆恶同一绝倒既而述之又烹小团亦兔饼也作诗报世美","f":"七言律诗","c":["争携勤意烹春风，终焉臧谷同一踪。","莫言不落第二月，须知所好非真龙。","窃香安得青琐趣，效矉颇惭西子容。","此言虽小有大喻，冯君转达裨时雍。"]},{"t":"与仲孺文仲述之作诗送仲弓赴籍田以之子于征为韵分得子字","f":"七言古诗","c":["凤园佳人孤凤起，草木无光春披靡。","红亭碧沼政高深，借问何由驻双履。","王涂开泰日月中，玉堂仙翁是知已。","瀛洲蓬岛未横飞，且向籍田聊尔耳。","北道仲容休说贫，东山太白谁比拟。","云汀荷芰供远凉，绕砌青青更兰芷。","丞相上马台阁空，长鞭往往城南指。","君身虽不作羊膻，自然尘表门如蚁。","清谈秀句得豪英，合抱他年郁松梓。","要须万口一同声，文恪风流今有子。"]},{"t":"次韵刘元因赠王幼安","f":"五言古诗","c":["真人拱南向，群英纷玉除。","趯趯动环海，夙怀思远摅。","争弹冠上尘，丘壑空故居。","之子建安裔，少长惟诗书。","每笑靖节君，归来但巾车。","拟倍万乘器，璨璨雕璠玙。","终然怒剑横，锐气埋忧虞。","须知梦镜中，所适难一如。","倘不达本原，触事成自诬。","试焚定慧香，矫首瞻六铢。","于此发深省，鼓瑟犹吹竽。"]},{"t":"次韵钱济明访定力僧及寄吴行古三首 其一","f":"五言古诗","c":["门前朝市喧，门内山谷寂。","昨来有虑心，到此了无迹。","况复有高僧，炯炯双眼碧。","渠今未易亲，拄杖鸣百尺。","知君从之游，勤我遥相忆。","安得双树傍，题名拂尘壁。"]},{"t":"次韵钱济明访定力僧及寄吴行古三首 其二","f":"五言古诗","c":["北阙来新荣，南溪抱初寂。","二子非世交，穷通偶殊迹。","诗书寄平生，孤云卷晴碧。","遥遥天一涯，回首无咫尺。","伊予亦乡邦，岂敢烦记忆。","尚误分隋珠，宵光动墙壁。"]},{"t":"次韵钱济明访定力僧及寄吴行古三首 其三","f":"五言古诗","c":["万物递先死，憧憧尝未寂。","中有不动尊，随方示形迹。","巨海何曾波，长天自来碧。","谁令失坦途，认此躯七尺。","空华初无根，欣厌浪思忆。","君今倘回光，奚须凿邻壁。"]},{"t":"寄题孔先生行歌亭","f":"七言古诗","c":["仁皇御宇作太平，朝廷玉立森贤英。","岩耕溪钓日寂寞，何独先生歌滍城。","遭世不比徐孺子，设心不愧司马承。","唐虞垂拱岂不盛，巢由亦自非公卿。","冥冥三圣妙相遇，六爻一半曾吞并。","倏遗象数入天籁，无声之中端有声。","有时鼓腹散秋步，有时击壤舒春情。","他年野叟得不尽，独与杖屦同纵横。","故知造物有深意，凤凰来仪治功成。","凤凰飞去定难久，直使先生为凤鸣。","先生道德初不死，先生歌声犹可听。","微风淅沥动草木，幽禽上下喧阴晴。","可怜双耳不到此，龙山滍水空危亭。"]},{"t":"送文仲省亲","f":"七言古诗","c":["曾参爱孝通神明，乐正子春游其门。","下堂伤足不忍出，流光至今覃后昆。","阿文全似李令伯，更相为命母与孙。","母年可惧发委雪，诸父骈头埋九原。","淮山之阳归未得，饮啜无以供晨昏。","脱身来寄岂获己，方寸摇摇旌旆翻。","飞云入望且还岫，况乃凯风吹棘薪。","白水真人挽不住，却垂故橐驰京尘。","皇天后土识君意，如君勿忧长贱贫。"]},{"t":"赋羲皇上人分韵得风字","f":"五言律诗","c":["妙达万物祖，天地生胸中。","坦腹夏日眠，五柳来熏风。","不弦虞舜琴，不觞唐尧钟。","况复羲皇前，岂直将无同。"]},{"t":"双璧歌寄马叔宝","f":"词","c":["君不见朱公托身天地中，四方万货常憧憧。","其间双璧最奇宝，分明日月生西东。","问公酬价初几所，一者千金一半此。","精神肉好非不同，侧视裁差厚薄耳。","公心夙悟谁得窥，但无故橐无留赀。","交贫族远富衣食，高义日与清风驰。","梁人有狱久不决，君臣相顾空嚬眉。","公来答问只一语，群疑亟判如蓍龟。","须知成效异霄壤，颇恨儒冠多失之。","多失之，胡弗思，他年薄俗待尔移，奈何璧价先自亏。"]},{"t":"送表兄华元翰赴四会尉","f":"七言古诗","c":["颐山颍水天西东，四载相望二千里。","我守枯株未得还，君逐飞蓬忽然至。","坐令桑梓落眼中，顿觉精神到尘外。","昔人逃空喜足音，况乃謦欬逢昆弟。","此会由来天予之，几日冷风清暑气。","君才荣华早驰名，荆国先生曾改视。","殿前射策失龙头，仕处波涛起平地。","胸中万虑不一施，却作明时岭南尉。","太夫人年七十三，诸子半掩黄垆逝。","兰陔养志独赖君，路远何由复迎侍。","当思有以慰其心，莫把光阴较荣悴。","本朝丞相岂不盛，尚辈流人已三岁。","君今补考裁秋冬，托身民上与之异。","萧条官府似僧居，春入梅花更堪醉。","要须相与无町畦，卷舌为喑真得计。","我家宅相世所知，矫首南云从此俟。"]},{"t":"送章显父推官改官","f":"七言古诗","c":["高堂夫人九十馀，一子晚方趋仕途。","前年封邑非子致，更待子荣新命书。","子纡墨绶来汉东，百里气和年屡丰。","声名籍籍动群耳，还似当时诗赋中。","诸公欲默安得已，争溯日边飞荐纸。","拔身左选归尚书，摅发平生从此始。","摅发平生从此始，未足为子增欣喜，所喜荣亲有期矣。","郡邑疏恩寿齯齿，斑衣儿啼奉甘旨。"]},{"t":"寄仲弓","f":"七言律诗","c":["道德不与禄位期，富贵自随时命至。","君宾以明故自销，禦寇于羊知去意。","城南岂复异墙东，诗句由来胜刺字。","直作朱游真丈夫，莫使小生敢相吏。"]},{"t":"次德符韵六诗 书怀二首 其一","f":"七言古诗","c":["秋容未觉成萧飒，脩竹疏桐阴四匝。","先生归驾挟西风，堕我南堂似凋叶。","对床邀月入高谈，梦想从来谢三接。","是非火作正炎空，忍与纷纷竞牙颊。","莫欺鸥鸟不知人，须信天机在眉睫。","妙哉托处无何乡，一念能回百千劫。","君诚有意涉其流，请为安行具舟楫。"]},{"t":"次德符韵六诗 书怀二首 其二","f":"七言古诗","c":["木杪秋风鸣飒飒，环步空亭日千匝。","忽迂征辔入衡门，共看霜轮上云叶。","紫烟收尽拟阶升，白露漙空欣手接。","何须清酌浣枯肠，自觉爽气滋双颊。","可怜末路竞牛毛，不悟劳生寄蚊睫。","向非霸处务功成，争得盟时遭智劫。","西山君故有风期，我亦从今理归楫。"]},{"t":"次德符韵六诗 分韵见简","f":"五言古诗","c":["幽人寄岩谷，志士从簪缨。","所尚初不同，出处皆有行。","夫子胡为哉，饮露餐秋英。","和璧以为质，黄钟以为声。","皎皎文史中，久作星斗明。","一见辄心降，端如屈人兵。","天意亦可料，祸患矧已经。","岂其礼乐时，而不收圭珽。","故知阿衡任，便是西山清。","我岂夫子徒，猥辱薮泽并。","驱车远过我，为我开天庭。","凡今落松麈，皆昔所未聆。","念此坐相阻，三十六峰横。","子言不子随，犹得座右铭。"]},{"t":"次德符韵六诗 与德符仲孺述之宿南堂分得客字","f":"五言律诗","c":["从容白露前，转盼一岁隔。","念我方促装，夫君复来客。","疏篁生晚音，霁月澹秋色。","此会岂易谐，未用询长陌。"]},{"t":"次德符韵六诗 南堂分韵得秋字","f":"五言律诗","c":["大火不东驻，高堂文字秋。","青蝇付驱除，白日堪迟留。","鸡痈落新烹，瓜疐收轻浮。","尚有明月在，倘能如故不。"]},{"t":"次德符韵六诗 曾园分韵得得字","f":"五言律诗","c":["藩城富池塘，所向辄荆棘。","天风初转西，朋簪共来北。","暑清随处幽，莲高向人默。","群鸥安在哉，我今均尔得。"]},{"t":"再宿南堂分韵得星字","f":"五言律诗","c":["夕云不成雨，冉冉东南征。","凉月挂河汉，鲜风起阶庭。","蛩韵响新织，萤光驶流星。","谁知亦有念，夙驾在青冥。"]},{"t":"分韵送德符还山得送字","f":"五言古诗","c":["秋风歘来归，秋事日夕动。","叶净嵩岭高，烟空颍川纵。","茅斋郁其傍，妙与猿鹤共。","拂衣问前途，不作河滨梦。","念君如病松，重以旻天恸。","未屠朱子龙，且集黄公凤。","伊予亦何为，于此迭宾送。","慎勿甘自埋，斯文要梁栋。"]},{"t":"送陈志仁赴河州司理","f":"七言古诗","c":["佳人宰木悬秋月，稚子霏霏洒清血。","枯风冷雨暗长天，借使端居亦心折。","问君夙驾今何之，万里关河西复西。","西州平昔但闻语，不意黄尘随绿衣。","将军雅歌飞玉觞，健儿如鼠马如羊。","桁杨生耳卧庭庑，日冀宾僚来畯良。","雪霜肃杀百草死，孤峰袅袅砂碛光。","城头笳鼓咽初晓，梦破衾裯皆异乡。","情钟矧复是君辈，只应矛槊攒中肠。","只应矛槊攒中肠，当思大人在高堂。"]},{"t":"送罗正之为两浙提刑","f":"七言古诗","c":["沧溟可枯山可移，公心独与天地期。","田间经术入州县，所至父老均儿嬉。","明明日月照肝胆，谓言吾民方阻饥。","回车为我作丰岁，要令国体无疮痍。","买臣郡去不持节，季真逸请非康时。","几年梦想在松槚，再拜一觞今得之。","乡人拥路识忠孝，雅慰平生良可知。","恩光到此何以报，行矣二浙如王畿。"]},{"t":"送裴仲孺为太和尉","f":"五言古诗","c":["波涛几千里，汹汹东南注。","故人帆北风，绝意蛟龙怒。","孤州何处城，几尽长江路。","鸿雁方来飞，霜雪且凝冱。","夜旦耳目中，动与客心忤。","况乃青云姿，四十困不遇。","有室常罄悬，未免折腰去。","命也天造之，智力岂其预。","端能一判然，楚越犹跬步。","崖边晚分携，君颜湛如故。"]},{"t":"送李子威致仕还乡","f":"七言古诗","c":["人间勋业如作诗，先生能诗端自知。","人间得丧如奕棋，先生能棋复何疑。","此身未免人间世，南北东西聊尔耳。","波涛风际涌丘山，不害江河为止水。","今年青春草木青，只有白发日日新。","先生一笑谢簪绂，归作三吴高尚人。","三吴寒暄几来去，童时闾井今犹故。","闾门亲旧半成空，往往子孙无托处。","先生第宅濒清流，负郭岁有千钟收。","挥金买酒醉花月，一局一篇方外游。","诸郎森森美且修，名声相继彻冕旒。","斑衣夙夕奉颜色，借问达官谁与俦。","他年再拜乡人后，犹能敬为先生寿。"]},{"t":"送散老归龙井","f":"七言古诗","c":["长安冥冥砂砾飞，道人趼足来何为。","师恩浃髓未云报，誓求卿相成其碑。","卿相盈朝成者谁，尚书妙墨侍郎词。","二公奔走天下士，士获一面犹几希。","道人愿力岂不满，文字乃今兼得之。","龙井神龙应护持，杖头星斗东南垂。","过门别我自色喜，我愧儒冠多背师。"]},{"t":"送荣子邕宰新郑","f":"五言古诗","c":["子渊陋巷居，子真岩下耕。","穷约一如此，不妨道自行。","矧君有民社，南面恩光荣。","问学□经济，岂不慰高情。","尔来几薰风，许洛犹声名。","还将模范心，农桑厚群生。","行矣舆人歌，国侨相弟兄。"]},{"t":"送郑州吴绶通直北归","f":"五言古诗","c":["霜雪下群木，江山拱高城。","旷然爽气中，幅巾日将迎。","精神在文史，朋旧皆公卿。","乃于功最时，冰泮人间情。","不待髭发改，乾坤付柴荆。","虚□本无系，风御聊尔行。","此邦郁多贤，向来集聪明。","德翁可君心，归欤助长生。"]},{"t":"次韵答交代俞樗年教授见简之什","f":"五言古诗","c":["吾乡蔼多士，夫子惟英才。","妙年双眸清，不为纷华开。","飞声动寰宇，著录争徘徊。","论说翕以定，端如匡鼎来。","著鞭青云衢，飘飘谢尘埃。","伯鸾赋五噫，少陵歌七哀。","岂比太平遇，得志无疑猜。","朝纲举天网，升黜常恢恢。","胡然落泮宫，犹歉南山台。","维今尧舜君，侧席方虚怀。","简拔到寒谷，未始由梯媒。","悬知器业成，指日登蓬莱。","伊予愧朴樕，聿来托高斋。","与君出处间，一一金石谐。","岘首郁苍莽，江流澹萦回。","龙卧缩头角，腾骧俟春雷。","君车亦难缓，行矣明诏催。","逸步从此分，驽驾安能陪。"]},{"t":"知府吕大卿饯别樗年以今我来思雨雪载涂分韵赋诗得雨字","f":"五言古诗","c":["使君出吾乡，门墙扫尘务。","诸生拥经来，翕然影响赴。","维时夫子贤，独入青眼顾。","河南拔贾生，千载一高步。","尔来十五年，终然阻鹓鹭。","如星不丽天，而乃西南雨。","晚逢使君车，亦复此邦驻。","从容平生欢，万事散朝雾。","江山飞雪霜，冉冉岁云暮。","我来踵规模，夫子故长路。","使君有高情，肃以豆觞寓。","宾僚集清夜，健笔落佳句。","行矣勿稽迟，青云答知遇。"]},{"t":"奉和邢舍人寄望之愚溪朝阳岩 其一","f":"七言绝句","c":["冷风不动水无声，倒影冲融漾太清。","公为少留谁会意，且凭诗句作长城。"]},{"t":"奉和邢舍人寄望之愚溪朝阳岩 其二","f":"五言古诗","c":["我闻紫微公，润色迈东里。","道阻未识面，驰心极云驶。","及此襄汉游，黄堂见名氏。","乃知吏民上，屹若楚山峙。","不以外自殊，夙兴酬寄委。","陶瓦焕穷阎，长堤矗江涘。","陋彼绳墨拘，畏首复畏尾。","坐令焚溺馀，衣食就安址。","流泽配羊杜，如水注无底。","念兹智略成，愚者岂同履。","胡为愚溪水，啸咏送寒晷。","虚涵万象幽，清绝一尘滓。","想公溪上心，所得似夫子。","岁律方峥嵘，抚事聊尔耳。","鼓枻得浮沉，观鱼谢竿饵。","应怜柳司马，爱身异桐梓。"]},{"t":"仲益约游延庆不至作此戏之","f":"五言律诗","c":["出门无他岐，一径指山麓。","馀寒弄晴阴，淅沥散轻玉。","我仆亦赏心，我马亦飞肉。","回首幕中英，文书正拘束。"]},{"t":"与节推李师益游谷隐习池","f":"五言律诗","c":["无心一何求，无垢一何洗。","与子入山来，放脚东风里。","岩根初著花，溪冰半流水。","一笑真偶然，松声为谁起。"]},{"t":"谢仲益惠兰","f":"七言古诗","c":["邻家得兰惜不得，数本分来好颜色。","儿童见之喜欲颠，惊回午梦松江侧。","起随斤斸聊斋前，面势栏干相并植。","氤氲犹带凤山云，弥天道安端我即。","璧丘亭高秀谷幽，想见僧移动晴碧。","根深丛迥无他虞，青眼东君方着力。","影连桂月共扶疏，香入梅风更引翼。","此心莫逆知谁何，金粟如来在东壁。"]},{"t":"次韵和端夫游谷隐","f":"五言古诗","c":["我生泉石中，清赏殊不足。","得官汉上来，邂逅亦溪谷。","他时长安尘，用此尘外赎。","城南百馀里，洒落自风俗。","招提密相忘，一一俨西竺。","缅维作者谋，永集荆楚福。","兴国最佳胜，千柱列岩屋。","前疏白马泉，后据双凤麓。","衲衣拥云外，拄杖倚藤竹。","天龙咫尺耳，入户体生粟。","谁为逢氏迷，不复枨也欲。","落英无再红，秀发岂常绿。","共将香火心，稽首千手目。","老僧独何为，瞬我掣电速。","已矣勿重言，良药反成毒。"]},{"t":"送望之移帅荆南","f":"七言古诗","c":["荆湖地与蛮獠通，江陵开府节制雄。","劲兵十万拥罴虎，鼓角声动波涛风。","列城如子满棋面，一一元帅呼吸中。","陛下钩帘抚天宇，妙选百辟今属公。","楚峰峻拔江汉广，晴光带影落渚宫。","悬知黄馘日饱饭，酣歌鼓腹均儿童。","裕陵松柏老霜露，钟山杖屦埋蒿蓬。","自从知已失君相，隼旟熊轼西复东。","赭袍可想不可见，十年一梦朝来空。","荆湖虽重岂留处，朝廷百度皆元丰。"]},{"t":"次韵魏道辅教授折梅怀荆帅望之","f":"七言古诗","c":["霜风未放江梅折，似向人间将价索。","冷然一解冰雪颜，花有天伦此其伯。","见卵求鸡亦非早，只今已觉和羹好。","殷勤犹是故时香，驿路一枝情淼淼。","我公所向物皆春，想见新花如汉滨。","新花故人政如此，欲了此心惟斲轮。"]},{"t":"送察推贾时以通直郎致仕还荆南","f":"五言古诗","c":["秋声起庭端，索索故时语。","几人清镜中，鬓发默自许。","东邻坐长叹，曰此非吾所。","平生困一官，湎若醉醪醑。","幸今豁然醒，可以事高举。","田园熟瓜芋，茅茨庇风雨。","向来避席人，把臂相尔汝。","年光虽云暮，犹足送寒暑。","斯言不浪酬，即日去幕府。","我惟尘世浮，贵贱等逆旅。","宽为百年期，形骸一丘土。","夫君脱身还，岂不知所处。","行矣数珠功，青天走龙虎。"]},{"t":"戏督潜亨作春羹","f":"七言古诗","c":["先生家□馀玉粒，粉以为饼陪春羹。","春羹品物谢时味，江流暖泛园中英。","晴窗对案忽举首，径走长须呼友生。","襄阳大夫腹如鼎，一著九牛犹未盈。","欢然放箸即过我，自叹珍庖逾大烹。","且言初意亦在我，属我府事留西城。","先生饭不饭俗客，若苦转眄相倒倾。","东风雕刻物物好，槎头缩颈尾不赪。","药苗蔬甲破土出，似与刍豢争功名。","应怜十载瘦藜苋，为我一除饥肠鸣。"]},{"t":"潜亨既见和再作此赠之","f":"七言古诗","c":["不作苟见如君平，不以礼屈如樊英。","扊扅坚卧三十载，凛凛风声人自倾。","墙东墙西过高马，往往愧汗面发赪。","岂知嗜欲极豺虎，白昼择肉无厌盈。","有时一饭稔奇祸，他年五鼎还遭烹。","狡兔未灭黄犬在，突兀上蔡空前城。","先生谢去既饱德，鼓腹之趣终难名。","更要我辈集匙箸，风雨不变如鸡鸣。","自怜头额乏奇表，几与齑盐同此生。","不愁捩手遂倾覆，只愁未至闻戛羹。"]},{"t":"次韵仲益解嘲","f":"五言古诗","c":["真宰干万物，物物相乘除。","童角赎以牙，毕竟均有无。","江山与丝竹，等为荐虚徐。","江山寂寞生，丝竹富贵馀。","要知谢安石，青史端几书。","达人眼目开，洞照无亲疏。","安用欣厌间，浪取尔与余。","独喜丰蔀幽，坐获骊龙珠。"]},{"t":"和欧阳彦立再用仲益前韵","f":"五言古诗","c":["山行迹未扫，倏忽岁已除。","东风从东还，天机动群无。","自怜藜苋中，遭时谢严徐。","两曜栖睫端，辉光照三馀。","尔来知昨非，一笑捐诗书。","虚堂自朝夕，与世成阔疏。","胡为公子贤，宾集亦到余。","鸣泉春际飞，聊复观跳珠。"]},{"t":"次韵和知府欧阳叔弼学士祷雨武侯祠","f":"七言古诗","c":["盲风日日吹尘土，谩说有年歌自古。","纷纷机械空作劳，况乃象龙求致雨。","黄堂学士极忧心，忍复宾前事悬堵。","倘助丰穰能出云，境内山川无不举。","丞相威灵凛一方，远瞩祠宫途可取。","旌旗拂晓动长庚，彷佛飞云趋两府。","精神洞达金石开，此意豫应神已睹。","况公爱民如爱子，不以斯民供鼎俎。","居士庵中常默然，田里人人自安处。","他时刀剑倚市门，往往买牛耕草莽。","心绝多岐礼义生，和气氤氲见眉宇。","惟天至聪下其耳，饱听欢谣荐佳语。","故宜神力导休祥，不待牲醪集轩庑。","胡为风旱久未宁，行矣斗柄将建午。","岂烦瑞祝更殷勤，祷处由来似尼父。","三分天下指掌间，顾此提封才一羽。","沛为甘泽定不难，沟浍纵横互吞吐。","坐令百谷暗郊原，会见腰镰分勤苦。","儒宫釜鱼端欲生，自笑年来遽如许。","虽无高廪并坻京，犹得朝昏鸣食鼓。"]},{"t":"宽夫率同诸公谒大悲寺观所画圣像以回向心地初分韵赋诗得初字","f":"七言古诗","c":["襄州城东十里馀，天仙大悲江上居。","白龙盘伏不敢动，澄波如练风前纾。","饱闻黔首喜相谓，微此妙相吾其鱼。","鼎来巾屦陪作礼，他年假道今题舆。","毫端愿力歘有感，手目纵横随卷舒。","高亭短棹青春里，云雨晓霁乾坤虚。","谁将五色染万物，物物可意难亲疏。","会须指顾发深省，此心长似楚香初。"]},{"t":"次韵和签判靳慎微奉议谒武侯祠有作","f":"五言律诗","c":["卧龙得风霆，天宇不难肃。","历数端何归，转昐移祸福。","庙食凛平生，光灵走川陆。","欲知庇斯人，绵延视巫祝。"]},{"t":"戏示柄","f":"五言绝句","c":["汝为狮子时，而作狮子吼。","他年毛骨成，一顾百兽走。"]},{"t":"次韵答詹成老谢密云龙之什","f":"七言古诗","c":["龙凤小团分禁户，往往称珍减前语。","元丰天子妙风雷，万古埃尘洒新雨。","壑源春贡识此心，不比豫州常枲纻。","卿云密密拥蜿蜒，御府仅能千百数。","匪颁台阁裁几人，恩逐味增沦骨髓。","帝乡仙去鼎湖空，井閟閤门犹玉乳。","龙髯虽在龙莫形，只有云留瑞民伍。","叶家所得最非常，好事殷勤始容取。","故人分赠不遐遗，怜我哀摧病方瘉。","莆阳英爽杳难攀，品目纵横谁捍禦。","仰惟笔削到茶经，亟以将诚归许与。","诗来寒谷歘然春，坐觉辉光满禾黍。"]},{"t":"次韵和成老谢何伯震","f":"七言古诗","c":["沧溟倒挽供瓶罍，少年取醉真豪哉。","天旋地转胆如斗，何独谪仙方逸才。","尔来意气折忧患，霜雪仍从双鬓催。","吾师吾友得浑沌，有口不复□□开。","宾筵竟日但趺坐，竦听摇犀谈玉杯。","中分鲁国两夫子，道德未逢贤者哀。","黄钟大吕相应和，儒风赖以扶倾颓。","伊予幸甚获亲炙，独愧不如匡鼎来。"]},{"t":"送石师稷还新昌","f":"词","c":["官失常丁民破产，仅有流波入春眼。","行人不管居人愁，但喜船头解初绾。","汀洲梦破白鸥前，归意峥嵘净如刬。","挽君君竟逐风东，瞑立西楼思何限。","念君心似岭云高，卷雨收雷依?嵼。","弟兄元恺正功名，独自巢由谢青简。","君今杖屦烟云中，我忆当年寄萧散。","情深人合吻天伦，相与宫商真律管。","可怜燕越阻寻盟，夜壑不留空旧馆。","只应石佛俨巍巍，为我旃檀荐诚款。"]},{"t":"游湘西道林寺用沈传师韵","f":"七言古诗","c":["赐还殊无功可论，放逐复向山前奔。","道人眸子炯如故，邀我累日游祗园。","御书新閤插霄汉，祝融严拱世所尊。","恍然身世脱尘垢，矫若鸿鹄辞笼樊。","是时秋老雨脚断，晴光万里凌朝昏。","北辰直下望天阙，纷纷郁郁卿云屯。","綵衣兰膳奉颜色，想见协气还闺门。","雁飞不到竟何许，日冀□□除瘢痕。","四年之中两到此，易摇难立怜孤根。","方寸倏忽丛百感，湘源白鹤空盈樽。","道人顾我亦无语，但指幡从风际翻。","由来否泰反其类，况逢主圣同羲轩。","而今而后戒覆辙，长记崇宁初纪元。"]},{"t":"谒女贞何氏祠","f":"七言古诗","c":["正月一日雨不休，朝来四望阴云收。","众阳扶导日轮出，辉光倏忽盈九州。","欣欣草木动新意，鸾凤鼓翅翔天游。","高山托处将半载，真人风韵长凝眸。","精神澡雪亦已久，欢言夙驾南冈头。","仙居楼阁拱形象，祥烟瑞霭檐间浮。","焚香再拜适我愿，想见王母同优游。","蟠桃不老春更永，人间变化知几秋。","轮囷重盖拥车马，气势赫赫移山丘。","万方有口莫敢议，勋劳自以为伊周。","门墙旦暮祝遐算，长守富贵无与俦。","于今扫荡一何有，白杨影里令人愁。","丈夫祈向乃如此，孰为女子能清脩。","功成直上紫霄去，遗踪犹向潇湘留。","我来不及叩真诀，真诀固在冥心求。","五行八卦自流转，生天生地生物稠。","骑龙跨虎越宇宙，岂但洗涤无愆尤。","他年谁作□仙传，□入高仙吾姓邹。"]},{"t":"醉饮","f":"五言古诗","c":["我生不嗜酒，断来仍十年。","前年窜岭表，去年斥湖边。","欲以禦瘴湿，乃复酒至前。","一杯复一杯，朝暮常醺然。","因之醉乡游，别是一山川。","日月不相促，万物同暄妍。","眼界绝尘污，耳根遗俗譞。","心平气自和，妙与天地全。","歠糟而餔醨，信以昔人贤。","琴外陶靖节，诗中李谪仙。","声利挽不回，昏昏长醉眠。","有师谁得之，我奉以周旋。"]},{"t":"谢衡州花光寺仲仁长老寄作镜湖曹娥墨景枕屏","f":"七言古诗","c":["道人秀骨生何许，若耶溪边清气聚。","不从章甫事功名，游历诸方参佛祖。","祝融峰下忽抬头，觑破虚空笑而舞。","折脚木床二十年，门外草深无寸土。","偶然消息落人间，挽出花光照今古。","我舟邂逅泊山前，雾捲云开见眉宇。","更知我自浙东来，曾拥旌旗尘督府。","千岩万壑绕樽罍，梦断卧龙谁是主。","为将池墨洒鲛绡，故国封疆归择取。","曹娥江接贺家湖，环以峰峦暝烟雨。","森森乔木动樵风，庙貌峥嵘閟神禹。","碑留遗刻蔡邕题，注目端为杨主簿。","子猷兴尽季真亡，彷佛棹声回远浦。","乾端坤倪渺莫穷，咫尺并包入庭户。","坐令乡思满潇湘，恨不归飞插双羽。","苍梧洞庭南北中，气象纵横随步武。","祗缘流放阻君亲，入眼虽奇若无睹。","道人方便巧施为，乃以家山慰心腑。","旧愆犹冀获湔除，恩锡馀年返农圃。","青鞋布袜谢尘埃，肯使高踪惭杜甫。"]},{"t":"除名","f":"七言古诗","c":["前年除名窜新州，今年除名窜昭州。","我名无实浪自得，坐此人间多怨雠。","恩深天地贷斧钺，除之又除名不留。","虽然未即听逐便，已觉此身民是俦。","裂冠毁冕散车马，幅巾杖屦西南陬。","行者争道舍争席，所向尔汝纷应酬。","洞山有语久弗契，忽然一笑知来由。","我追我随非我患，那用避如韩伯休。"]},{"t":"将往昭州示柄","f":"五言古诗","c":["与汝暂相别，南作昭州行。","昭州距零陵，坦坦十日程。","音信易来往，勿动异乡情。","但自勤读书，思索厥义精。","圣贤如日月，为汝出光明。","脩身识根本，力践以其诚。","发为文字间，笔墨自纵横。","零陵豪杰士，张邓尤高名。","汝其师事之，北面听指令。","分阴古所惜，况乃汝后生。","省定汝母外，谨勿他事萦。","皇恩极天地，我罪终从轻。","还家知有时，欣见汝向成。","用为祖母寿，慰叔及弟兄。","携汝返乡国，重增门户荣。"]},{"t":"饮桂州酒示柄","f":"五言律诗","c":["好酒如好人，虽久略不变。","炎凉互推移，气味愈可见。","岂若茅柴浆，多为众所贱。","举杯吾得师，足以警閒燕。"]},{"t":"题义明定慧庵","f":"七言绝句","c":["结草依山名定慧，于此冥心第一义。","垆香深炷席帘垂，老僧不见庵外事。"]},{"t":"答曾敷文有书见寄","f":"五言绝句","c":["客寓天地间，本无南北异。","此语安从生，却成相钝置。"]},{"t":"戏作","f":"词","c":["作自我作，止自我止。","莫被傍人，推倒扶起。"]},{"t":"一切诸佛子","f":"五言古诗","c":["我心如虚空，无物可伦比。","湖南与岭南，谁行复谁止。","宝山得楼居，屹枕乐川水。","森森青琅玕，却暑几千里。","团蒲叠双趺，炉烟凝然起。","圆觉首楞严，遮眼聊尔耳。","幽禽忽来鸣，一切诸佛子。"]},{"t":"榴花","f":"七言古诗","c":["阁东阁西安石榴，两株相映花枝稠。","山高江阔万木叶，独此烂熳开不休。","有如牙门集缨绂，碧油幢外红光浮。","又如青天驻羲御，火龙鳞鬣惊人眸。","朝朝莫莫看愈好，直若有意宽离忧。","无穷归念姑且置，栏边取醉商声讴。"]},{"t":"仙宫岭","f":"五言古诗","c":["晓云生岭端，遮日成清阴。","炎氛遽辟易，兴逸安能禁。","仙宫风尘表，高高百千寻。","石路上曲折，健足犹难任。","绰约两仙子，双鬟坐沉吟。","巫觋意何许，门窗藤蔓深。","樵叟向我言，自古传至今。","去州五十里，有峒郁森森。","陶家李家女，年各胜巾衿。","恍惚若逢遇，相与登崎崟。","一朝作蝉脱，英魂不坠沉。","乡人共祠之，彷佛来顾歆。","水旱祷辄应，民吏同所钦。","此宫乃行宫，春秋荐诚谌。","言已叟仙去，四望祛烦襟。","荥山直南耸，龙岳山朝壬。","越王连佛子，密山秀孤岑。","回环万峰峦，插云皆玉簪。","滔滔两川流，会合通梧浔。","渔舟糁木叶，城郭几突黔。","虚徐韵长松，飞鸣集珍禽。","须臾烟霭青，遐迩浮祲祲。","变化纷见门，饮酒时一斟。","我罪贷五鼎，我躯重千金。","虽居瘴疠乡，肯使瘴疠侵。","囊衣完旧裾，匣剑存初镡。","气听谢耳力，谁到无弦琴。","子期久冥漠，天地为知音。","中和王度新，祈招咏愔愔。","赐环谅匪朝，聊以写我心。"]},{"t":"送子发还零陵","f":"七言古诗","c":["我自罪大当投荒，君胡为乎亦遑遑。","马蹄舟楫困川陆，省定违离萱草堂。","由来孤操绝流俗，屹与巨镇遥相望。","洞庭以南渺无际，气象突兀收湖湘。","平时事事不入眼，惟恐有愧如毫芒。","色难直到古人处，以其绪馀均四旁。","馀波邂逅亦及我，使我方寸失感伤。","我亲白发照闾里，我身局蹐瘴疠乡。","两儿随母仍旧寄，骨肉星散知几方。","乾坤子初无薄厚，恩为雨露威雪霜。","二柄交持不偏用，万汇生成如审量。","我虽弃掷五岭外，亦必有日蒙恩光。","故人亭边是归路，尚得握手输中肠。","将分无可为君语，独有高义无时忘。"]},{"t":"有感","f":"七言律诗","c":["云回雨歇天欲晴，鹁鸠唤妇皆和声。","山南山北树阴里，欢然相趁争飞鸣。","伊予流窜止平乐，妻孥尚寄潇湘城。","五岭横空唤不闻，不如鹁鸠犹有情。"]},{"t":"闻彦和过桂州 其一","f":"五言古诗","c":["人臣难有己，况复顾其家。","忘家以徇国，致主为勋华。","割爱非不仁，成功讵能加。","御史殿中杰，指摘生疵瑕。","昔如鹄矫云，今如兔罹罝。","省符到房陵，驱逐殊喧哗。","即日出门去，形影自天涯。","羁皇携众雏，惊散随风沙。","渺漭失处所，何由书报嘉。","君心固已定，闻者空伤嗟。"]},{"t":"闻彦和过桂州 其二","f":"五言古诗","c":["削迹投炎荒，有吏督其后。","一州一易之，稍缓辄訾诟。","所历多官僚，岂无亲且旧。","前车覆未遥，不敢略回脰。","谁谓桂岭僧，于君独勤厚。","沐浴君发肤，浣濯君领袖。","使君霜柏姿，凛凛出尘雾。","真风绝顾瞻，高义激颓仆。","乃知世外情，非复世间构。","呜呼君何忧，时命不终缪。"]},{"t":"自警","f":"五言古诗","c":["看书勿苦多，多看目力眊。","作文勿苦多，多作心力耗。","初虽莫觉悟，久乃成悔懊。","维心神所居，惟目神所造。","开阖出入间，神伤气亦暴。","所以古真人，丁宁有深告。","平时当勤行，况复处炎燠。","况复病初愈，力始胜巾帽。","老母在乡邦，倚门望佳报。","尤宜决择精，全神以自好。","收目以内视，冥心以存奥。","气舒形康强，外务一除扫。","生理保安完，天恩垂覆帱。","归看老莱衣，欢欣长舞蹈。"]},{"t":"感叹","f":"七言古诗","c":["一犬捕执将祭神，群犬随之号极声。","恶伤其类乃如此，虽至苟贱亦有情。","人于天地最为贵，诗书礼乐开聪明。","推恩尚欲极万物，而况等列皆簪缨。","奈何心忍所不忍，相残相贼争功名。","因知微畜反可尚，使我感叹无由平。"]},{"t":"送李师聃祖道长官赴衡州耒阳令","f":"五言古诗","c":["视国如视家，爱民如爱子。","秉心金石坚，古人概如此。","今人亦古人，但患物转徙。","遑遑声利间，自不明本已。","安能使元元，一以父母比。","问其所居位，广分国百里。","问其所食禄，尽出民骨髓。","奈何莫之思，颠倒以为是。","祖道于今古，问学妙穷理。","内重外物轻，识者久叹美。","宰制得耒阳，何啻牛刀委。","导达圣主恩，千仞决溪水。","雨旸随指呼，丝谷饫邻鄙。","明神实听之，日夜介福祉。","君虽不求通，轩冕自难已。","工部有英灵，吾知为君喜。"]},{"t":"示徐道人","f":"五言古诗","c":["道人千里来，触热废寝膳。","问其何所为，但云求识面。","南方诸公门，二年走略遍。","亦有苦苦留，诸事颇安便。","念未见侍郎，跋涉遂忘倦。","皇帝与天同，深恩满州县。","瘴乡宁久留，行复侍金殿。","卖药至京师，礼数隔贵贱。","姓名且难通，况敢冀垂盼。","汝言岂吾知，答之一笑倩。"]},{"t":"谕徐道人少唱喏","f":"五言律诗","c":["孔明拜床下，德公初不止。","道人必见喏，我令勿复尔。","道人非孔明，喏拜不相似。","维我德公心，寥寥无彼此。"]},{"t":"咏菊","f":"词","c":["菊，菊。","丛丛，簇簇。","种阶除，脱岩谷。","玉干碧鲜，金英黄郁。","争妍无小桃，结好有修竹。","满泛醇酒千杯，高簪道巾一幅。","庭前子美休作诗，篱外渊明自留目。"]},{"t":"咏竹","f":"词","c":["竹，竹。","濒江，绕屋。","声泠泠，影矗矗。","霜雪难侵，尘埃莫渎。","梢云齐老松，带日映寒菊。","箨置顶上高冠，叶成樽中美禄。","行看威凤饱相从，不但子猷情最熟。"]},{"t":"有所叹","f":"五言古诗","c":["亲者如路人，故者如世雠。","路人与世雠，反与亲故侔。","无日不同处，无事不同谋。","自谓腹心托，长久逾千秋。","不知祸有孕，有识所深忧。","一旦乘间作，四顾谁依投。","往往舍之去，掉臂不回头。","却思故与亲，大寒索衣裘。","聪明天资高，反已亦易求。","及此早觉悟，厥疾犹可瘳。"]},{"t":"莫钓矶","f":"五言古诗","c":["饭罢何所之，曳履江之湄。","粼潾白石间，得石殊瑰奇。","瑩然如紫玉，屹立平不攲。","振衣坐其上，聊以垂纶丝。","吾钩既不曲，吾饵亦不施。","持钓非有钓，与鱼均莫为。","鱼乐吾已得，吾意鱼岂知。","投竿归去来，晨昏以为期。"]},{"t":"下鸥台","f":"五言古诗","c":["此心久已灰，入鸟无惊猜。","轻鸥翔集处，邀我相徘徊。","方圆十丈许，疑是天所开。","锵金两滩濑，簪玉千崔嵬。","耳目肝肺中，何由着纤埃。","鸥虽不解饮，屡舞劝我杯。","清狂与酒狂，似此知几回。","我归有日矣，鸥飞安在哉。"]},{"t":"读颐卦","f":"七言律诗","c":["灵龟不语亦不食，深之又深乃其息。","清泠渊中能事毕，天长地久无终极。","朵颐自朵非自得，何暇外观惟汝即。","吾言易行休更惑，抱一故为天下式。"]},{"t":"九日对菊","f":"五言古诗","c":["不雨江亦乾，草木翳尘土。","重阳到眼前，菊蕊犹未吐。","邻家一株来，高才尺四五。","种之小庭中，亦自足风矩。","摘叶以当花，茱萸可为伍。","泛我流霞杯，喜色动眉宇。","颓然逍遥游，妙处有谁睹。","渊明何人斯，东篱傲今古。"]},{"t":"道乡歌","f":"词","c":["要识道乡去处，只在微尘里许。","不立四至封疆，不问二仪寒暑。","日月常放光明，鸟兽率同歌舞。","其俗无举无非，其民无喜无怒。","别是一种乾坤，全异九州风土。","师旷倾耳莫闻，离娄拭目莫睹。","谁知有个冥蒙，踏着从来门户。","入也不动脚跟，居也不记年所。","行住坐卧虚徐，色声香味愚鲁。","偶然成矩成规，未尝为鼠为虎。","任他卜度纵横，迥脱机关取与。","人间天上无明，可谓自今自古。"]},{"t":"梦臣惠潘谷墨 其一","f":"词","c":["老潘飞蹑烟霞去，墨宝流传能几许。","尚方犹以比庭圭，况复人间故人处。","夫君好事追前贤，巾袭深藏二十年。","雨旸燥湿莫知数，毕竟挺然金石坚。","一朝酒发南箕舌，信在言前可中辍。","有如印弄掌握间，棱角虽刓终一决。","著书天禄垂无期，云将掉头吾弗知。","但欣厚意厚若此，来仙阁上信双眉。","我有歙州韫玉石，琢成高秋远天碧。","平时长自水流珠，未省呼童助涓滴。","我有常州饱霜毫，千钱一管价不高。","真行隶草字百万，劲锋凛凛方遒豪。","绛人陈元乃其伍，相得欢甚谁能禦。","心灰缘此亦复然，和我精神动寰宇。","便涤砚，便操笔，便启轩窗磨此墨。","敲冰佳纸适及门，罗列千张耀晴日。","也吟诗，也作文，也把黄庭模右军。","并包万类入方寸，倏忽变化生乾坤。","君不见老子绝学故能学，君不见孔子捐书故能书。","因君起我书且学，我书且学孔老俱。","孔老俱，竟何如，写我长句酬勤渠。"]},{"t":"梦臣惠潘谷墨 其二","f":"五言古诗","c":["潘谷卖墨时，吕翁尝过之。","指授长生诀，举世那能窥。","但称众墨中，谷墨最珍奇。","一旦内药成，解去逃喧卑。","忽忽期月后，来与丹元期。","夜饮晓分手，丹元初不知。","仍留墨数片，属元付其儿。","有儿旋其门，顶白元惊疑。","细诘所以然，始知谷如斯。","谷仙今几年，谷墨今在兹。","静言人间世，舟壑常密移。","朱颜兀槁木，绿发垂素丝。","借令富贵极，毕竟将奚为。","谷乎真可人，得墨吾得师。"]},{"t":"梦臣再以墨来","f":"五言古诗","c":["孙郎文史外，所好墨而已。","龟玉藏椟中，涓辰乃开视。","未尝轻示人，每戒卞和耻。","谓予心事同，分惠真可喜。","磨去五之一，馀者恰盈咫。","印弄棱角刓，前言戏之耳。","苍头忽踵门，喘汗殊不止。","恍疑皂囊药，无因至于此。","亟取启缄封，入眼胜双鲤。","其长应天数，其光动晴晷。","当暑尚挟纩，岂但什袭比。","且云此不刓，品色尤更美。","始知雅意来，要以补前毁。","想初闻语时，废书频拊髀。","兵法善致人，所致必如指。","一朝下两城，曾不费一矢。","坐令鼎足心，成辙乱旗靡。","堂堂莫我过，势若建瓴水。","墨果多乎哉，一一是孤垒。","齐城七十二，受降从此始。"]},{"t":"留别张云立立之","f":"七言古诗","c":["来迁梦破知何处，今君归去仙宫路。","江头舟楫岭头云，曾许乘风邀月住。","翛然三载与君同，信我此心惟白鹭。","白鹭忘情亦有情，君更情多无量数。","天绘亭前不忍分，远送我来欣进步。","霜凋万木见孤松，颜色青青独如故。","湘南湘北旧光阴，从此回头但烟雾。","得志轩前藕未花，梅率小桃先已露。","与君同醉复同醒，千顷池塘渺新霔。","好随鱼跃趁风雷，飞上青天休反顾。"]},{"t":"桂州紫极观主求亭名名曰转斗而示此句","f":"七言绝句","c":["转降适斗藏初九，上清密语谁知有。","七星峰顶紫霞前，占得辉光长不朽。"]},{"t":"信中以诗来因次其韵送之","f":"七言古诗","c":["道言谁复书诸绅，潇湘江上逢斯人。","向来滨死入魑魅，胸腹洞然无甲鳞。","炎氛吹风作旗靡，玉楼倒影明蒿里。","孤心还逐冷云飞，历历长亭不知几。","圣王开了睹天庭，妙脱筌蹄合喙鸣。","个中无可无不可，智者亦迷何处名。","浑沌兼忘倏与忽，有口鼻如欣莫咄。","北山之北草堂深，怨鹤惊猿它自物。"]},{"t":"送李方几仲司户","f":"五言古诗","c":["我迁汉阳居，君为建阳掾。","江山几千里，何当重会面。","身世波上萍，岁月弦上箭。","自古以叹嗟，不古乃独见。","为仁岂由人，弘道道该遍。","万生无终穷，同我一方便。","壑源春焙香，黄鹂静中啭。","简书有光阴，归坐亦可燕。","此事入高明，了了为君见。","舟车暂西东，勿受离情转。"]},{"t":"题蒋彦回绯桃轩","f":"七言古诗","c":["何仙饥食王母桃，王母唤去瑶台高。","怀中核乃长生种，付与东君谁适遭。","蒋侯本是神仙族，扬州骑鹤飞游遨。","回也不愚愚故道，不肯钓海连六鳌。","变邓家田作蓝田，产玉成芝天所褒。","柳将眼觑竟何睹，花着心觅空自劳。","东风莫逆花柳外，洞然启尽扃鐍牢。","铺张云霞驻迟日，暖红牵梦春陶陶。","恍疑何仙只春是，衣绣还乡导旗旄。","蒲萄浪兀弄明月，宁比倒着宫锦袍。","从今结就千年实，食之工力逾圭刀。","闻说扬州鹤知得，鼓翼已先鸣九皋。"]},{"t":"题成立道飞香阁","f":"七言古诗","c":["碧池千亩红莲花，敕书楼下醇儒家。","跻民仁寿逢主圣，欣与万邦无叹嗟。","六经变化天地阔，何处不可为生涯。","只今耆域在庭户，信手掇取皆灵芽。","气运回环助调燮，各正性命逾尘沙。","是渠病愈我亦愈，红莲影里薰风斜。","阴功乘香飞北极，上帝首肯群仙誇。","赠之丹桂一千尺，攀条直上凌苍霞。"]},{"t":"少隐惠所尽潇湘雪景 其一","f":"七言绝句","c":["永州城北十五里，二水初同为一水。","天花开玉满前飞，人在故人亭子里。"]},{"t":"少隐惠所尽潇湘雪景 其二","f":"七言绝句","c":["前年深冬一丈雪，岩拥朝阳渡黄叶。","鸬鹚插颈梦圆时，天作高山付双睫。"]},{"t":"少隐惠所尽潇湘雪景 其三","f":"七言绝句","c":["将谓雪消无觅处，元来只在毫端住。","为余展出冻云天，一片潇湘宛如故。"]},{"t":"戏浯溪长老伯新","f":"词","c":["永州怀素精草书，毫端万象纷卷舒。","浑身是眼看不破，一笔至今藏物初。","浯溪得之不自用，却要他人书作图。","蓦然打个筋斗去，觅纸觅绢一物无。","急将床上被来拆，手忙脚乱纵横铺。","五云和尚巧言语，扫尽六幅裁须臾。","叠了又开开又叠，喜欢胜获衣内珠。","二三子笑几绝倒，左右僮仆咸惊呼。","宁比酸寒杜陵老，海图拆应家人须。","脱巾漉酒解龟当，表里空旷真丈夫。","吾行天下何啻半，常恨眼前无此徒。","那知兴发乃方外，与彼嗜好同根株。","小中现大大可睹，跳出规矩渠非愚。","他时风雪夜参半，灰炉冰冷灯影孤。","坐披破絮似鱼网，数挽不掩皴肌肤。","只应侍者隔壁私自语，我师为谁说法声呜呜。"]},{"t":"观华光长老仲仁墨梅","f":"七言古诗","c":["我从梅花海里来，惊此两枝堂上开。","不由天降非地出，道人作么生栽培。","无缝塔子通一线，放光照醒陈根荄。","玉蟾银汉雨初霁，半启琼室通瑶台。","香云漠漠护颜色，世眼欲睹诚难哉。","不如取酒共春醉，一杯一杯复一杯。"]},{"t":"次韵和范信中同游花药有作","f":"五言古诗","c":["花药山去来，难遇此天日。","深衣书眼青，摩衲禅眼碧。","雁峰相与高，可以同我适。","浮云当面开，千里见丛荜。","况紫盖祝融，插天日未夕。","正尔无能名，僧来乞题石。"]},{"t":"湘阴邓氏翠微洞","f":"五言绝句","c":["卧云云无心，听松松有韵。","快哉耳目中，吾今亦同分。"]},{"t":"送成老赴西安","f":"七言古诗","c":["先生出逢尧舜时，自当勋业追皋夔。","胸中廊庙乃州县，雪霜次骨西安驰。","旁观往往屡兴叹，色初不变心希夷。","但云将圣世所大，乘田委吏皆尝为。","道通为一无不可，等君事耳何高卑。","高斋高居万物表，清献清风天下师。","此心妙与此公契，莫或遑处今其谁。","民歌仁恩到天耳，天须默荐君王知。","坐令四海归一握，阴阳变化随设施。","行即验矣姑且置，聊引花前金屈卮。"]},{"t":"偶书","f":"五言律诗","c":["朝读一卷经，暮读一卷书。","一卷复一卷，三藏与五车。","儒释本不异，昧者自亲疏。","昧者不足道，明者当何如。"]},{"t":"送陈公晦","f":"五言律诗","c":["寂不闻凤鸣，双耳聋已久。","聿来丹山子，一旦惊户牖。","旧听歘我还，喜气薄牛斗。","箫韶方九成，飞勿众禽后。"]},{"t":"吴公蔚将还滁阳出所集述德堂诗作此送之","f":"七言古诗","c":["述德高堂在何许，述德高人欣可睹。","彭州梦破知几年，遗爱远追曾大父。","至今民数旧邦君，每及吴公歌且舞。","述而行之德莫穷，定可周流浃天宇。","谁令千里便归休，炯炯此心元自古。","四百六十五甲子，貌若岩松傲风雨。","胸中何啻法界宽，普集尘沙诸佛祖。","一如一切悉皆如，迥脱拘挛不踰矩。","从横肉眼讵能窥，但见鼻间常栩栩。","只应高与老人星，长现升平瑞明主。"]},{"t":"咏张公奭庐墓有芝三本","f":"五言古诗","c":["此芝初无根，生自孝诚里。","孝哉本于诚，非缘利心起。","无芝非所怍，有芝非所喜。","不期芝有无，秀出乃如此。","养志勤色难，送终极哀毁。","既葬不忍归，结庐独留止。","孺慕秋复春，泪接九泉水。","比邻或未知，天已知之矣。","因芝示邦人，邦人争赞美。","会逢当路贤，荐此八行始。"]},{"t":"书公孙卷末","f":"五言古诗","c":["韩范天下贤，褒贬不妄出。","舌端有春秋，所与惟其实。","一举十五丧，富贵所难必。","公孙贱且贫，兹事乃能毕。","心追古人高，迹付今人述。","二老首形容，昭劝无终日。","伊予特后闻，叹恨颇自失。","东望天山平，风松正萧瑟。"]},{"t":"代书寄清老","f":"七言绝句","c":["从来游戏常三昧，出语纵横无忌讳。","老聃全与释迦同，人畏犹云亦当畏。"]},{"t":"题双芝轩","f":"七言古诗","c":["难弟难兄强氏子，太学声名耸多士。","同时流辈久公卿，犹傍短檠业文史。","今年鉴拔贡辟廱，伯仲皆升从此起。","集英春晓拱天临，龙头妙绝人间喜。","鸾台凤阁便腾骞，况乃吾乡有前比。","向来胸中宇宙宽，包尽华夷无复委。","发为勋业助尧仁，肯令元凯常专美。","倘如不信视双芝，端不虚生漫黄紫。"]},{"t":"和路主簿思雨","f":"七言律诗","c":["造物初无欠与馀，盈虚消息自洪垆。","晴空已见云如火，秋穫难期米似珠。","剧邑君宜形远虑，泮宫我亦念群枯。","若为惊起苍龙睡，赖有新诗胜大雩。"]},{"t":"独坐偶书","f":"七言绝句","c":["梧桐沐雨响玲珑，帘幕阴阴飏晚风。","讲诵乍闻人语息，满床书史兴何穷。"]},{"t":"寄濠州陶户曹","f":"七言绝句","c":["台枕长淮耸半空，登临应得古人风。","水天上下碧无际，莫获观鱼与子同。"]},{"t":"勉毕元明","f":"五言律诗","c":["男儿数偶奇，不必苦嗟咨。","颜子犹箪食，庄生亦布衣。","百年容易老，万卷卒难窥。","致力宜为者，腾骧自有时。"]},{"t":"谢罗朝奉惠柏栽","f":"五言律诗","c":["惠我柏虽小，观君意实深。","欲令儒服者，同此岁寒心。","月映庭雕玉，风来韵响金。","公车已驰节，不及待清阴。"]},{"t":"和钱签判赠胡都曹","f":"七言绝句","c":["公馀来访习家池，楚楚王孙桂一枝。","九十春光未过半，倒罍尤喜有前期。"]},{"t":"和路主簿喜罢役法并酬范奉议见寄","f":"七言律诗","c":["因革纷然岂用情，由来消息与时行。","奏封直指财并力，造法当期实应名。","可使华夷渐润泽，不烦衡石自均平。","将明况是忧民者，即见熙熙百室盈。"]},{"t":"酬黄秀才见寄","f":"七言律诗","c":["自期谋道不谋身，不逐轻狂戏此春。","读史穷经求在我，攀龙附凤彼何人。","一言逢主未如志，百结成衣肯叹贫。","早晚病除堪属思，新诗莫厌起予频。"]},{"t":"偶书","f":"七言绝句","c":["底事爰丝不自高，倾心剧孟久游遨。","元来缓急叩门处，徇义忘躯胜我曹。"]},{"t":"和郡主簿绝句九绝 其一","f":"五言绝句","c":["管鲍当年志，风霜固自如。","信衰缘嗜欲，岂在数行书。"]},{"t":"和郡主簿绝句九绝 其二","f":"五言绝句","c":["俗论长纷若，微言仅梦如。","逢君挥玉麈，胜读十年书。"]},{"t":"和郡主簿绝句九绝 其三","f":"五言绝句","c":["肘后虚金印，梅仙职偶如。","升高元自下，功业异时书。"]},{"t":"和郡主簿绝句九绝 其四","f":"五言绝句","c":["塞北亢喉地，并门子所如。","六花无处用，却縠自诗书。"]},{"t":"和郡主簿绝句九绝 其五","f":"五言绝句","c":["能诗唐太白，善赋汉相如。","元帅真文举，应先荐祢书。"]},{"t":"和郡主簿绝句九绝 其六","f":"五言绝句","c":["取友能无怍，初终贵一如。","陈张遗辙在，试展马迁书。"]},{"t":"和郡主簿绝句九绝 其七","f":"五言绝句","c":["咳唾成珠玉，吾侪孰子如。","更勤潘氏学，岂愧乐尚书。"]},{"t":"和郡主簿绝句九绝 其八","f":"五言绝句","c":["提履归何处，观花笑自如。","期君求向上，糟粕古人书。"]},{"t":"和郡主簿绝句九绝 其九","f":"五言绝句","c":["春风暗杨柳，相见意何如。","虽愧江淹笔，狂言为子书。"]},{"t":"送诗卷还参寥","f":"七言绝句","c":["盈轴新诗字字清，弥天元不愧声名。","茂陵消渴无医处，赖有醍醐得细倾。"]},{"t":"和路子高微雨中至山光寺","f":"七言律诗","c":["野阔天低四望赊，霏微膏雨兆休嘉。","早钟郁郁穿云断，官柳垂垂夹道斜。","邂逅庭前方指柏，逡巡木末已栖鸦。","杨朱易服归来处，荷笠收车几万家。"]},{"t":"送监作院潘供备 其一","f":"七言律诗","c":["盟府功臣奕世孙，低回筦库尚随群。","干戈分职名虽武，诗酒忘怀格自文。","倾盖二年嗟往事，赢粮一日指行云。","江梅欺雪南枝发，如綍新除定此闻。"]},{"t":"送监作院潘供备 其二","f":"七言律诗","c":["飘飘雅致孰如君，旋辟西轩置酒樽。","振木岂惟闻白雪，断缨仍许醉黄昏。","长亭风顺已言别，小圃春回空自繁。","惆怅潜斋不知处，何年携手却重论。"]},{"t":"简王正父觅酒","f":"五言绝句","c":["瓮面蛆浮玉，槽头水滴珠。","未能如茂世，聊与义城俱。"]},{"t":"寄周彦廉","f":"七言绝句","c":["楚水不风鱼逝远，霜天初月雁飞高。","履穿袍敝浑无暇，目断心驰祗自劳。"]},{"t":"和刘知录见寄并简阳先生","f":"七言律诗","c":["刘郎爽气晓霜晴，阳子高怀宝鉴明。","虽幸竹林容入会，每惭布鼓独无声。","一杯葵藿真佳趣，五鼎牛羊谩宰生。","廊庙他年调燮手，不妨潜室且和羹。"]},{"t":"和阳先生见赠","f":"七言律诗","c":["万卷藏书肯自閒，沉涵圣道欲晞颜。","片心既与人寰远，逸驾宁容俗士攀。","嗟我曳裾胶扰处，荷君置榻寂寥间。","藜羹玉麈清何限，每到斜阳不忍还。"]},{"t":"求刘知录澄泥香炉","f":"七言绝句","c":["千卷新书三叠琴，青灯炯炯夜沉沉。","野人此外无馀好，只欠澄泥一炷深。"]},{"t":"大雨中接宪使因成小诗呈阳先生","f":"七言绝句","c":["霜风折木雨如倾，敛板泥中厮役并。","遥想先生鼓琴罢，观书正傍短灯檠。"]},{"t":"次韵盛长官觅酒","f":"七言绝句","c":["九万鹏程戢怒飞，驱愁却叹酒无威。","頖宫官冷非文举，一斗何能醉十围。"]},{"t":"次韵胡秀才遗桃花","f":"七言律诗","c":["灼灼桃源数朵红，青禽传到荜门中。","傍人只喜窥春色，达士元来寄祖风。","谩说几经千岁赏，会须一笑万缘空。","沉香散处圆蒲稳，花自蕃鲜体自同。"]},{"t":"次韵俞秀老建隆道中","f":"七言绝句","c":["道人不独是诗豪，曾把沧溟注一毛。","破晓联镳访孤寂，致身如在太山高。"]},{"t":"次韵慕公实","f":"七言律诗","c":["从来文史足三冬，何事明时作退翁。","刺口岂能论扰扰，冥心直欲似空空。","半轩苍莽雨初霁，一钓清泠月正胧。","好把晨昏付香火，个中真乐更无穷。"]},{"t":"次韵钱?雪中","f":"五言律诗","c":["六出飞琼玖，云愁正腊天。","寒声生密竹，爽气彻纯绵。","故苑风初静，重楼月向圆。","何当酬此景，蘸甲引金船。"]},{"t":"次韵王贤良赠阳先生 其一","f":"七言绝句","c":["脩涂几阅岁终穷，鹤唳猿啼蕙帐空。","杖屦何当归旧隐，静看五柳飏春风。"]},{"t":"次韵王贤良赠阳先生 其二","f":"七言绝句","c":["嚣嚣所乐本非穷，曾向真乘悟色空。","闻说近添方外友，清谈应得晋人风。"]},{"t":"二月十五日朝拜建隆桥上偶作","f":"七言绝句","c":["单衣迎犯晓风清，斗柄回南月尚明。","柳密行人看不见，轮蹄相属但闻声。"]},{"t":"清明日游大明道中","f":"七言绝句","c":["春风荡漾遍天涯，纵步郊原事事嘉。","不许游人同所得，竹林深处试龙茶。"]},{"t":"和通判王定国承议游竹西 其一","f":"七言律诗","c":["流年忽忽又残春，策杖郊原肯厌频。","往古来今何足校，閒花幽草自争新。","旋开酒蚁成高会，共解名缰作逸民。","随处怡然真有味，不须千里忆吴莼。"]},{"t":"和通判王定国承议游竹西 其二","f":"七言律诗","c":["一霎狂飙破晓阴，春光极目几千寻。","会须胜事追莲社，更约幽人访竹林。","渺渺平田涵白水，萧萧苍桧聒清音。","郑虔才大犹遭骂，重愧持杯许脱簪。"]},{"t":"送胡适道秀才东归","f":"七言律诗","c":["十年星散忽相逢，寂寞芜城古頖宫。","一炷澄泥窥祖要，三卮浮蚁对春丛。","牢刍岂解留天骥，云路还闻逐塞鸿。","莲社故人如见问，为言涉世百无功。"]},{"t":"次韵蔡宽夫解元暮春见怀 其一","f":"七言律诗","c":["九十青阳安在哉，临风搔首谩迟回。","春于我辈非无意，诗必先成为有才。","拖架酴醾香破麝，翻阶芍药大逾杯。","病除更约归愚子，浮蚁犹堪席地开。"]},{"t":"次韵蔡宽夫解元暮春见怀 其二","f":"七言律诗","c":["惊红簌簌点苍苔，春去黄鹂唤不回。","九藏脉参知我病，千人笔扫见君才。","会须磥砢挥谈麈，方悟蜿蜒落酒杯。","命驾相应怜叔夜，笑颜一月几能开。"]},{"t":"又倒用前韵","f":"七言律诗","c":["休论花草与楼台，借得江南叠嶂开。","纵使春归无觅处，何妨人乐自持杯。","棋如孙武推多算，诗似颜渊已竭才。","早晚竹林修故事，更看君笔灿昭回。"]},{"t":"送及之贤良游钱塘","f":"七言律诗","c":["屏迹人间二十年，下帷搰搰究陈编。","新书曾入老商盼，高弟谁如颜子贤。","策杖青山元有约，挥金红药故无缘。","岂宜便隐双溪去，优诏行闻坠日边。"]},{"t":"送俞秀老归维扬","f":"七言律诗","c":["踏雪驱驱原宪履，御风猎猎老莱衣。","情投岂比钟山出，兴尽远同剡水归。","炀帝池边松荫远，维摩室内烛光微。","携筇促席相羊处，应记当年接下机。"]},{"t":"雪中呈秀老原道","f":"七言绝句","c":["引舟西上正隆冬，千里隋堤雪翳空。","恰似常年三月尾，柳花凌乱逐东风。"]},{"t":"戏孙扬休","f":"七言律诗","c":["耿耿僧坊寄日边，晚移穷巷避諠阗。","羹藜不饱同攻苦，秣马言归独处先。","木叶已随风力远，霜轮行作璧形圆。","衣冠返敝文昌路，何似高堂坦腹眠。"]},{"t":"简李子温推官","f":"七言律诗","c":["太冲当日号无兄，苗裔于今更绝伦。","力究本原书簏富，唾成珠玉锦囊新。","龙门久欲攀高躅，鼎角方欣觇后尘。","借问竹溪馀地否，狂吟聊伴谪仙人。"]},{"t":"寄周廉彦","f":"七言律诗","c":["不见冰清几岁周，乘风举翮恨无由。","濒江松竹三秋后，隐几情怀万事休。","险阻艰难空蚁斗，东西南北正萍浮。","与君相好如兄弟，莫惜微言为置邮。"]},{"t":"风起有感","f":"七言律诗","c":["秋来郁郁但炎蒸，一夜狂飙骇四邻。","断送冥鸿尤得势，留连残暑更无因。","镜中鬓发虽非故，窗下灯檠渐可亲。","勿似安仁儿女态，由看节物重悲辛。"]},{"t":"次韵崔浚明见赠","f":"七言律诗","c":["谁为冥行作指南，青灯黄卷久间关。","逢君岂测陂千顷，许我时窥豹一斑。","骥足拘挛虽未展，龙鳞腾踏会须攀。","如何暗把隋珠掷，欲报殷勤只强颜。"]},{"t":"将至南京简应介中 其一","f":"七言绝句","c":["得之平陆我登车，不见群优孟子诛。","只恐鼻端无好质，归时依旧腹空虚。"]},{"t":"将至南京简应介中 其二","f":"七言绝句","c":["几日风尘困马蹄，忽瞻孤塔献云霓。","双眸已似清江洗，况入亭城见角犀。"]},{"t":"将至南京简应介中 其三","f":"七言绝句","c":["先生不得醉红裙，何以留连逆旅人。","故苑池台老秋色，頖宫讲罢走车轮。"]},{"t":"将至南京简应介中 其四","f":"七言绝句","c":["直谅多闻许我亲，迷途从此遂知津。","社中忽怪尔来进，曾向睢阳见异人。"]},{"t":"九月朔夜闻雨","f":"七言绝句","c":["尘濛蛛网暗东斋，设榻君能待我来。","昨夜梧桐有消息，会须急上宋王台。"]},{"t":"送曹巨源之南都","f":"七言绝句","c":["高堂且置琴中操，骏马初驰陌上尘。","无限清风与明月，一时分付属閒人。"]},{"t":"挽石适中 其一","f":"七言律诗","c":["剸犀翻羽早称奇，亨会难遭但布衣。","不使牙筹烦伯仲，果然玉树照庭闱。","灵台久已天昭鉴，奏籍初闻子发挥。","三世簪缨正无恙，如何遽作百年归。"]},{"t":"挽石适中 其二","f":"七言律诗","c":["南明山下读书堂，曾许寒生借烛光。","高义岂殊亲骨肉，令人无复念家乡。","那知十载天涯别，忽起三泉薤露伤。","追恨故时携手处，不能执绋助棺傍。"]},{"t":"和朱仲明见赠闻琴","f":"七言律诗","c":["子期骨发已埃尘，谁谓知音不复生。","触处折杨争属和，独君忘味叹遗声。","荜门寒日正多暇，玉麈高谈相与清。","鹤举鱼沉重惆怅，一樽麦酒荐藜羹。"]},{"t":"次韵赵希元忆处州梅花","f":"七言律诗","c":["万花头上占天工，得意开时斗未东。","破月麝脐来馥郁，横烟玉树净玲珑。","暖归故蕊应欺雪，人在他乡正御风。","借问殷勤动诗兴，忘机争似鹿皮翁。"]},{"t":"冬至夜梦中作","f":"七言绝句","c":["炉烟飒飒对团蒲，暮去朝来只自如。","还见人间好时节，群阴消尽一阳初。"]},{"t":"雪中简次萧求团茶","f":"七言绝句","c":["竹上松间敲玉花，最宜石鼎荐灵芽。","蓬门不识苍龙璧，借问风流宰相家。"]},{"t":"和晦之见赠听琴","f":"七言律诗","c":["忌子当年妙五音，曾令按剑革初心。","昭文重愧难成曲，潘岳胡为缪见寻。","在昔丝桐尝弃置，到今山水自高深。","何当共造无弦处，莫使渊明擅此琴。"]},{"t":"再和晦之","f":"七言律诗","c":["举世欣欣濮上音，丝桐还寄长卿心。","知君韶濩思千载，劲节松筠挺几寻。","万籁息时霜剑立，一灯明处夜堂深。","他年振铎收遗器，岂愧云和瑟与琴。"]},{"t":"倒用前韵","f":"五言律诗","c":["我有一张琴，穷高更极深。","瓠巴那解鼓，师旷杳难寻。","寂寂三冬夜，悠悠万古心。","衣冠遍天宇，谁为作知音。"]},{"t":"次韵道卿寄同僚","f":"七言律诗","c":["从事休嗟我独劳，何如对雪咏瀌瀌。","圣贤潋滟冬来美，朋旧绸缪老不凋。","仇览初年犹主簿，田单他日竟屠聊。","上方侧席搜遗逸，未易沅湘作大招。"]},{"t":"督巨源和诗","f":"七言绝句","c":["诗成七步有家风，底事淹留岁已穷。","应笑枚皋太容易，欲令句似长卿工。"]},{"t":"郊行呈彦祖","f":"七言绝句","c":["迟日初乾雪径沙，等閒联骑过田家。","长官标格风尘外，衰草坡前报晚衙。"]},{"t":"和彦祖寄次萧","f":"七言绝句","c":["格外参军事事嘉，竹窗全是子猷家。","清狂上客知何处，恨不同燃柏径槎。"]},{"t":"柬理堂","f":"七言律诗","c":["主人生长绮纨中，标致分明儒者同。","结构不因穷鼎俎，栖迟聊欲事磨砻。","血漫霜剑悲王凤，坐拥云鬟笑马融。","铭府功勋久牢落，会须腾踏振家风。"]},{"t":"戏社正李子温","f":"七言绝句","c":["红莲上客有新篇，不见长安驿使传。","寄语持纲社中老，可怜三百青铜钱。"]},{"t":"寄阳先生","f":"七言律诗","c":["长揖公卿不转头，五车图籍指虔州。","屑榆肯使家风坠，谢币空令世俗羞。","弄凤骑龙诚莫及，坏车杀马恨无由。","嵩山出处君知否，似与高人作覆辀。"]},{"t":"发山口堤上","f":"七言绝句","c":["烟笼官柳柳笼堤，风引澄波细细移。","骏马不知鞍上意，回头已是获麟陂。"]},{"t":"渡汶河","f":"七言绝句","c":["旧来纸上得河名，今日横过彻底清。","浚治早经神禹手，若为汩汩尚西行。"]},{"t":"过中都王彦章庙","f":"七言律诗","c":["一时多难见忠臣，力拥貔貅捍此城。","岂为圣人曾作宰，由来壮志在留名。","铁鎗埋没今何处，庙食追崇事若生。","功业已经华衮赠，只应长伴斗魁明。"]},{"t":"慎夺堂","f":"七言律诗","c":["百鍊终成绕指柔，何人劲节拟横秋。","目前轩冕自来去，堂上诗书尝讲求。","风度绮疏香漠漠，月移苔砌竹幽幽。","将军此意生平事，不似空言不到头。"]},{"t":"閒轩","f":"五言律诗","c":["结构俯危城，公馀杖履轻。","事随尘自远，心与水长清。","隐几鱼方乐，开窗雨乍晴。","憧憧渡头客，谁会此时情。"]},{"t":"王宪湖上分韵得荷字","f":"七言律诗","c":["使星明处是天河，习习轻飙生芰荷。","自有芝兰随后乘，更容簪履侍鸣珂。","未甘城鼓促清赏，聊与汀鸥分素波。","异日定应如此少，云雷行欲起龙梭。"]},{"t":"送王宪赴阙","f":"五言古诗","c":["凤诏传天北，輶轩指建章。","既能思贾谊，何患老冯唐。","况是高门庆，从来美誉彰。","灵台悬宝镜，峻节凛秋霜。","庖刃诚难敌，黄陂岂易量。","承家但清白，报国颇施张。","属部分氂犬，终朝事锦囊。","收功殊俗士，知已恃明王。","此去堪前贺，胡为独倍伤。","昔沾淮水润，今借德星光。","折柳故多恨，衔环空不忘。","他年重望履，应已步岩廊。"]},{"t":"送王裘仲侍亲赴阙","f":"五言律诗","c":["置榻初相得，膏车忽起行。","秋风无限事，麦酒不胜情。","原宪何曾病，丘明竟有声。","从容湖上语，他日看功成。"]},{"t":"试日怀世美","f":"七言绝句","c":["挟策刚为泮水行，暖风迟日试诸生。","姚黄魏紫知何许，独有杨花扑砚轻。"]},{"t":"戏王宽之 其一","f":"七言绝句","c":["晚来闻说醉黄封，弦管欣欣急雨中。","应笑西邻少风味，一炉沉水对梧桐。"]},{"t":"戏王宽之 其二","f":"七言绝句","c":["墨龙翻海几朝昏，今日晴阴似欲分。","不道谷飞多作蛊，犹教歌扇遏行云。"]},{"t":"次韵世美简别乘喜雨","f":"七言律诗","c":["一勺龙泉甫到城，滂沱疑是泻南溟。","枣心正为斯民赤，菜色宁忧异日青。","击壤田家方自得，掷金诗轴已交形。","病来无复高阳兴，宴喜空烦置醁醽。"]},{"t":"湖上杂咏 其二","f":"七言绝句","c":["何处清风作晚凉，解衣相与面沧浪。","青萍紫芡令人恨，遮却琉璃万顷光。"]},{"t":"湖上杂咏 其三","f":"七言绝句","c":["华亭标格本青云，邂逅西湖秋复春。","作意一声君会否，鹓鸾集处是真人。"]},{"t":"湖上杂咏 其四","f":"七言绝句","c":["疾病经旬厌药杯，喜君折简傍湖来。","浓云几败乃翁事，赖有南风为约开。"]},{"t":"湖上杂咏 其五","f":"七言绝句","c":["滨湖一一敞雕栏，自是黄尘不汝閒。","今日舒眉宁易得，未应轻作剡溪还。"]},{"t":"湖上杂咏 其六","f":"七言绝句","c":["霜蹄桧楫久途穷，暂喜天时人事同。","濯热不须三岛去，高谈落麈自生风。"]},{"t":"湖上杂咏 其七","f":"七言绝句","c":["嵯峨秀色雨晴时，极目城隅更落晖。","何必鲈鱼动秋意，好携双屐便言归。"]},{"t":"登楼","f":"五言律诗","c":["荜门真蚁穴，旷快一登楼。","天地投双睫，诗书落九州。","栏杆元诘曲，日脚更迟留。","借问同来客，能同此意不。"]},{"t":"听泉","f":"五言律诗","c":["天中悬日月，激激正鸣泉。","洗耳岂吾事，披襟聊石边。","焦桐无杂弄，佩玉有群仙。","欲识偃溪语，于今蹄与筌。"]},{"t":"呈同社","f":"七言律诗","c":["太史占星久寂寥，高阳烟月但蓬蒿。","人才岂是非前日，天意端如待我曹。","万古衣冠归指顾，一时天地入风骚。","他年南北参商去，知有青编破郁陶。"]},{"t":"马上 其一","f":"五言绝句","c":["策马戴残星，郊原破暑清。","人间千万事，并入一时情。"]},{"t":"马上 其二","f":"七言绝句","c":["晴空云物不留形，大块遥呈一点青。","闻说嵁岩隐君子，何当北面问黄庭。"]},{"t":"马上 其三","f":"七言绝句","c":["孤冢如山官路傍，老农指似是前王。","可怜烜赫当年计，牧笛樵歌付夕阳。"]},{"t":"追凉","f":"五言律诗","c":["三伏流金石，端居若探汤。","古松摇落照，芒履促追凉。","天壤知谁似，形骸亦自忘。","何须北窗下，始解到羲皇。"]},{"t":"次韵参寥访和靖先生故居","f":"七言绝句","c":["湖边高节与谁邻，落落寒松往往皴。","就使衡门已尘土，不妨千古自阳春。"]},{"t":"关氏四照亭","f":"七言绝句","c":["孤亭缥缈枕烟霞，面面江山不用赊。","何日乘风指星纪，与君携手逐飞鸦。"]},{"t":"寿星院观竹","f":"七言绝句","c":["祗园寂寞耸高材，自有鸾凰接翅来。","回首壶觞散桃李，日斜风动使人哀。"]},{"t":"送王幼安赴举","f":"七言律诗","c":["几年幽径委榛芜，此去寒生孰子如。","笔下奔腾三峡水，胸中突兀五车书。","岂惟丽赋欺弘正，会使清时识仲舒。","富贵由来皆骨相，门闾高处莫趑趄。"]},{"t":"送二弟赴开封举","f":"七言绝句","c":["古人捧檄缘亲喜，况值秋风一鹗天。","相与抟空谢蓬艾，归来称寿綵衣鲜。"]},{"t":"椹涧马铺壁间有黄元明诗因次其韵","f":"五言律诗","c":["武当在何许，漠漠西南天。","雷电正多事，道途如去年。","参差挥麈约，妨废把书眠。","破我征鞍恨，清诗犹灿然。"]},{"t":"纯孝墓","f":"七言律诗","c":["禽犊何知尚母怀，黄泉相见岂宜哉。","向非雅意一杯去，安得迷心中路回。","自古功名随日月，于今庙貌倚崔嵬。","可怜肉食趋朝者，粪壤纷纷久已灰。"]},{"t":"仙翁山下遇王由正用驿壁二诗之韵见意 其一","f":"七言绝句","c":["物外风期迹已陈，须知日月去来频。","我今欲换神仙骨，还向山前逢异人。"]},{"t":"仙翁山下遇王由正用驿壁二诗之韵见意 其二","f":"七言绝句","c":["烟雨冥冥不肯晴，无因飞步数峰青。","朅来山下倾谈麈，全似江边语醉醒。"]},{"t":"阻雨呈由正 其一","f":"七言绝句","c":["秋风吹雨入疏棂，永夜漫漫双眼明。","借问泥涂困行李，何如南亩念西成。"]},{"t":"阻雨呈由正 其二","f":"七言绝句","c":["炼石曾闻补就天，如何淫雨尚绵绵。","只应知我班荆意，欲使从容夫子前。"]},{"t":"过仙翁山","f":"七言绝句","c":["群山环拱一山青，曾驻仙翁竟得名。","前日授书非我事，旄头不耀正休兵。"]},{"t":"穰东驿壁间有诗因次其韵","f":"七言绝句","c":["箠辔驱驰长眼花，更堪风雨作泥沙。","邮亭准拟一醉倒，白酒黄鸡无处赊。"]},{"t":"林堠驿壁间有诗因用其韵","f":"词","c":["日转山亭寂寂，梦迷蝴蝶双双。","何独渊明寄傲，吾今亦是南窗。"]},{"t":"早行","f":"五言古诗","c":["朝来由气锐，前程入马蹄。","天形随月见，斗柄傍人低。","路转才萦白，沙平岂辨泥。","露零欺鬓发，犬吠隔蒿藜。","恍惚南柯梦，参差逢氏迷。","比经十里堠，始报一声鸡。","似脱关中日，如趋圯下蹊。","脩真空有术，习懒信无梯。","行李几时北，武当犹在西。","谁知贵公子，角枕正清闺。"]},{"t":"顺阳东山下小池","f":"七言绝句","c":["行尽江山知几重，山前池沼尚残红。","尘埃满眼欣相见，驻马垂杨夹岸风。"]},{"t":"将到均州","f":"七言绝句","c":["武当孤垒插天西，一见都忘渴与饥。","倦客惟贪早休歇，不知匏系未成归。"]},{"t":"次韵宇文伯脩题清溪驿梅花","f":"七言律诗","c":["骥尾曾容蹑后尘，柳花榆荚古河滨。","天衢事业已腾世，山驿诗篇知几春。","梅萼故应如异日，风骚仍得慰幽人。","须知犹是枯株在，早晚吹嘘近紫宸。"]},{"t":"入试院呈同事章显父推官及监试柴承之朝奉","f":"七言律诗","c":["汉江汹汹不知休，江上谯门鼓角秋。","匹马崎岖随国事，同心邂逅得儒流。","何妨蟋蟀床头急，况是芭蕉雨脚收。","别乘端容共萧散，从今相与傲浮丘。"]},{"t":"午枕觉怀世美","f":"七言绝句","c":["睡乡天地肃秋风，日日欣随宰我踪。","靖节有人须命驾，道途何事不相逢。"]},{"t":"李元礼墓","f":"七言律诗","c":["几年模楷揭天中，四海衣冠尽影从。","必待名人裁受谒，遂令当世比登龙。","求通谩负孔融志，执御难追荀爽踪。","回首高门正如市，悲风猎猎起长松。"]},{"t":"泛汉江 其一","f":"七言律诗","c":["汉江衮衮接天流，百里舟行一转眸。","白浪激风鸣战鼓，青山迎棹走长虬。","均阳已断南柯梦，酂上还惊宋玉秋。","南望祖茔能几驿，王程不得下荆州。"]},{"t":"泛汉江 其二","f":"七言绝句","c":["谁家游女戏江滨，才见舟来竞敛身。","须信文王风化远，至今犹自被行人。"]},{"t":"泛汉江 其三","f":"七言绝句","c":["山束长江激箭奔，扁舟冲破白鸥群。","故人正在笙篁里，一枕滩声谁与分。"]},{"t":"怀襄阳","f":"五言律诗","c":["寄迹襄阳北，无因吊古人。","卧龙应索寞，堕泪想鳞皴。","不作庞公客，空回徐庶身。","风流终自若，他日引车轮。"]},{"t":"次韵显父睡起偶成","f":"七言律诗","c":["杜门无复辙声来，一日刚肠欲九回。","消遣但能眠白昼，较量犹胜走黄埃。","霜风却暑通归路，篱菊要人荐寿杯。","同我此心君最切，更将幽思托清才。"]},{"t":"留别显父且约相见于南阳","f":"七言绝句","c":["风帆催我上轻舟，不得追陪自在游。","山路马蹄新雨霁，早来携手百花洲。"]},{"t":"次韵监试喜引试有日","f":"七言律诗","c":["朅来凡韵续高张，凫鹤居然分短长。","鸣鼓未窥才气勇，悬河先饫古今详。","三秋欲半月方好，万事兼忘心更凉。","只愿真贤起山国，异时端委赞垂裳。"]},{"t":"湖上联句","f":"五言绝句","c":["遥岑舣舟见，野思过桥生。","兴尽回兰棹，归鞍月正明。"]}]};